var EXTRA=[{dot:"gray",j:"Wiener klinische Wochenschrift",h:"Innesto di hamstring: allograft e autograft, stesso risultato ma tempi operatori diversi",v:"piccolo studio randomizzato pilota monocentrico: nessuna differenza nei punteggi funzionali a un anno fra allograft e autograft di hamstring nella ricostruzione del LCA; l'allograft riduce solo il tempo operatorio. Non è l'innesto di tendine quadricipitale della tua pratica.",pmid:'42678533',doi:'10.1007/s00508-026-02805-w',temi:["lca","innesto","hamstring"]},{dot:"gray",j:"SICOT-J",h:"Un confronto pilota fra protesi convenzionale e un sistema robotico meno noto",v:"studio pilota che mette a confronto la tecnica convenzionale con l'assistenza robotica OMNIBotics HLS Kneetec (Corin) nella stessa serie di pazienti; risultati preliminari, sistema diverso da VELYS.",pmid:'42679216',doi:'10.1051/sicotj/2026057',temi:["protesi robotica","allineamento","sistema alternativo"]},{dot:"gray",j:"Acta Orthopaedica",h:"In Norvegia i pazienti scelgono l'ospedale per la protesi in base a cosa, non solo alla vicinanza",v:"studio di registro nazionale norvegese su oltre 62mila pazienti: le preferenze di scelta del centro per protesi d'anca e di ginocchio sono un tema organizzativo più che clinico, ma influenzano i percorsi reali dei pazienti.",pmid:'42670833',doi:'10.2340/17453674.2026.46430',temi:["protesi totale","organizzazione sanitaria","registro"]},{dot:"gray",j:"Cureus",h:"Ricostruzione del LCA con sutura meniscale insieme: la funzione migliora, senza un gruppo di confronto",v:"coorte prospettica indiana a braccio singolo: dolore e punteggi funzionali migliorano nei sei mesi dopo ricostruzione del LCA con sutura meniscale concomitante, nessuna complicanza osservata, ma manca un gruppo di controllo per isolare il contributo della sutura.",pmid:'42677330',doi:'10.7759/cureus.113786',temi:["lca","menisco","riabilitazione"]},{dot:"gray",j:"American Journal of Sports Medicine",h:"Botta e risposta sull'AJSM: il LET rende davvero equivalenti gli innesti negli atleti d'élite?",v:"lettera e risposta degli autori originali (con Andy Williams, gruppo Fortius Clinic di Londra) su un lavoro che discute se il rinforzo laterale renda equivalenti innesti diversi negli atleti d'élite: il dibattito scientifico resta aperto, nessun dato nuovo.",pmid:'42676097',doi:'10.1177/03635465261466186',temi:["let","dibattito scientifico","atleti"]},{dot:"gray",j:"The Bone & Joint Journal",h:"Un editoriale del Bone & Joint Journal: l'allineamento non basta più a spiegare il successo della protesi",v:"editoriale che invita a guardare oltre il solo allineamento componente-per-componente nella protesi totale di ginocchio, verso una lettura più multidimensionale — bilancio dei tessuti molli, cinematica, percezione del paziente — del successo clinico.",pmid:'42674580',doi:'10.1302/0301-620X.108B9.BJJ-2026-0910',temi:["protesi totale","allineamento","editoriale"]},{dot:"gray",j:"Arthroplasty Today",h:"Un nuovo sistema robotico senza immagini migliora la precisione nella protesi monocompartimentale, in laboratorio",v:"studio cadaverico: un sistema di navigazione robotica imageless raggiunge una precisione di posizionamento maggiore della strumentazione manuale nella protesi monocompartimentale; dato di laboratorio, non ancora clinico.",pmid:'42677196',doi:'10.1016/j.artd.2026.102118',temi:["protesi monocompartimentale","protesi robotica","cadavere"]},{dot:"gray",j:"Arthroplasty Today",h:"Nella protesi totale sotto i 50 anni, la basetta tibiale non cementata tiene bene a lungo",v:"coorte monocentrica: la basetta tibiale in titanio poroso non cementata mostra una tenuta clinica solida in pazienti giovani, con un follow-up medio di 7,6 anni.",pmid:'42676903',doi:'10.1016/j.artd.2026.102129',temi:["protesi totale","impianto","pazienti giovani"]},{dot:"gray",j:"European Journal of Physical and Rehabilitation Medicine",h:"Anche la testa conta: strategie di stimolazione mentale dopo la protesi di ginocchio",v:"revisione sistematica e meta-analisi: le strategie di stimolazione mentale (immaginazione motoria, tecniche cognitive) come complemento alla riabilitazione dopo protesi di ginocchio mostrano un segnale positivo, qualità degli studi inclusi eterogenea.",pmid:'42678178',doi:'10.23736/S1973-9087.26.09226-9',temi:["protesi totale","riabilitazione","aspetti cognitivi"]},{dot:"gray",j:"ACR Open Rheumatology",h:"Cosa chiedono davvero i pazienti a un percorso dedicato al dolore dopo la protesi",v:"studio qualitativo su pazienti e operatori coinvolti nello sviluppo di un modello di intervento precoce sul dolore dopo protesi di ginocchio: bisogni informativi, tempestività e continuità delle cure emergono come priorità condivise.",pmid:'42675641',doi:'10.1002/acr2.90139',temi:["protesi totale","dolore postoperatorio","percorso di cura"]},{dot:"gray",j:"Cureus",h:"Nella revisione di protesi con grande perdita ossea, innesto strutturale o cono poroso: chi fallisce meno",v:"revisione sistematica e meta-analisi di studi non randomizzati: nei difetti ossei importanti della revisione di protesi (grado AORI 2-3), il tasso di fallimento asettico fra allograft strutturale e cono poroso metallico resta un confronto indiretto, non randomizzato.",pmid:'42676773',doi:'10.7759/cureus.113772',temi:["protesi totale","revisione","perdita ossea"]},{dot:"gray",j:"Arthroplasty Today",h:"Passare da carta a digitale migliora la qualità dei registri di revisione protesica",v:"analisi di un registro nazionale di artroplastica: il passaggio da raccolta dati analogica a digitale aumenta completezza e accuratezza dei dati sulla revisione di protesi di ginocchio, con ricadute dirette sull'affidabilità delle statistiche nazionali.",pmid:'42677219',doi:'10.1016/j.artd.2026.102125',temi:["protesi totale","registro","qualità dei dati"]},{dot:"gray",j:"Medicine and Science in Sports and Exercise",h:"Negli adolescenti con dolore femoro-rotuleo, più dolore vuol dire meno forza del quadricipite",v:"studio trasversale australiano: gli adolescenti con dolore femoro-rotuleo hanno una forza estensoria del ginocchio più bassa dei coetanei sani, e più dolore riferito si associa a una forza ancora più ridotta; percorso conservativo, non chirurgico.",pmid:'42679045',doi:'10.1249/MSS.0000000000004125',temi:["patellofemorale","adolescente","conservativo"]},{dot:"gray",j:"Knee Surgery & Related Research",h:"Chi ha avuto un'artrite settica del ginocchio rischia di più con la protesi, anni dopo",v:"revisione sistematica e meta-analisi coreana: un pregresso episodio di artrite settica dell'anca o del ginocchio aumenta il rischio di infezione periprotesica e di reintervento dopo protesi totale, rispetto a chi non l'ha mai avuta.",pmid:'42675535',doi:'10.1186/s43019-026-00348-y',temi:["protesi totale","infezione","fattore di rischio"]}];
var SCOPERTE=[{t:"Un disallineamento di 2 centimetri nell'esoscheletro del ginocchio può triplicare lo sforzo articolare",v:"Un gruppo di ingegneria meccanica dell'Università di Scienza e Tecnologia di Nanchino ha modellato al computer — e verificato con elettromiografia su volontari — quanto un disallineamento fra l'asse di rotazione di un esoscheletro indossabile e quello del ginocchio umano amplifichi le forze di interazione fra i due. Con appena 2 cm di scarto, il momento flessorio può più che triplicarsi in una direzione. Non è chirurgia, è biomeccanica applicata alla robotica indossabile — ma è lo stesso principio dell'allineamento che, cambiando scala, decide il successo di una protesi.",pmid:'42655429',doi:'10.3390/s26165119',temi:["bioingegneria","esoscheletro","biomeccanica"]},{t:"Un modello linguistico può preparare il chirurgo a parlare di costi prima della protesi? Quasi.",v:"Un gruppo cinese ha messo alla prova un modello linguistico di grandi dimensioni nel generare, a partire dalle cartelle cliniche di 80 pazienti, una lista di punti da toccare nel colloquio preoperatorio sui costi della protesi di ginocchio. La copertura degli elementi giudicati necessari da un panel di esperti è alta ma non completa (85%), e in una minoranza di casi il modello genera contenuti giudicati a rischio dagli esperti: uso possibile solo con revisione clinica sistematica, mai come sostituto del colloquio diretto sui costi.",pmid:'42656464',doi:'10.3389/fmed.2026.1899060',temi:["intelligenza artificiale","protesi totale","comunicazione clinica"]}];
var SOC={1:{video:"Una revisione sistematica di 51 studi su 4.153 pazienti pediatrici e adolescenti mostra che aggiungere una tenodesi extra-articolare laterale alla ricostruzione del LCA si associa a re-rotture più basse con ogni tipo di innesto — per la prima volta anche col tendine quadricipitale, 0% contro 7,7% senza LET. È un segnale coerente con l'indicazione universale sul LET, costruito però su serie retrospettive: nessun RCT ha ancora confrontato direttamente innesto o LET nello scheletricamente immaturo."},2:{video:"Una coorte di 103 ginocchia, inizialmente randomizzata a due target di correzione nell'osteotomia tibiale alta (70% o 62% della linea di carico), mostra a 10 anni che il target più basso resta sotto-corretto più spesso e si associa a più conversioni a protesi. Il confronto sulla conversione complessiva resta però sottopotente per numerosità, come dichiarano gli stessi autori: un'indicazione a restare vicino, ma non oltre, il 70%."},3:{video:"Un registro amministrativo su oltre 10mila pazienti pediatrici mostra che a 10 anni l'artrosi post-traumatica è meno frequente dopo sutura meniscale (1,5%) che dopo meniscectomia (2,3%) — rischio relativo 0,65, un intervallo che esclude l'assenza di differenza. In entrambi i gruppi, un secondo intervento per rigidità articolare resta il segnale di allarme più forte. Rinforza, su una scala molto più ampia del solito, il principio della riparazione meniscale nel paziente giovane."},4:{video:"Una meta-analisi di 6 studi comparativi su 645 protesi totali robot-assistite mostra che l'allineamento funzionale richiede meno release dei tessuti molli e anticipa il recupero del movimento rispetto al meccanico classico, ma questi vantaggi precoci non si traducono in un miglioramento funzionale superiore a un anno. Coerente con RACER-Knee e con la revisione critica del 1° settembre: la precisione tecnica non garantisce da sola un vantaggio che il paziente percepisce."},5:{video:"Una revisione narrativa multidisciplinare riassume come stratificare il rischio tromboembolico ed emorragico e come gestire nel perioperatorio gli anticoagulanti cronici nei pazienti candidati a protesi totale di anca e ginocchio. Nessun dato originale: è una guida pratica costruita su raccomandazioni esistenti, con un messaggio chiaro — un regime paziente-specifico, con un team multidisciplinare, bilancia meglio i due rischi di un protocollo uniforme."},6:{video:"Una coorte retrospettiva di 80 pazienti mostra che un BMI più alto, un intervallo più lungo fra trauma e chirurgia e le lesioni meniscali associate si legano in modo indipendente a un danno cartilagineo più esteso al momento della ricostruzione del LCA. Il campione è modesto e gli stessi autori descrivono i risultati come esplorativi, ma il segnale è coerente con il principio di non allungare i tempi fra infortunio e intervento senza una ragione clinica precisa."},7:{video:"Uno studio diagnostico su 110 pazienti confronta una ricostruzione RM assistita da intelligenza artificiale con la ricostruzione standard, usando l'artroscopia come riferimento, per il grading delle lesioni del legamento crociato posteriore. La qualità d'immagine migliora nettamente e la diagnosi delle lesioni complete è buona, ma la tecnica resta debole proprio sulle lesioni parziali — le più difficili da gestire clinicamente, che richiedono comunque conferma artroscopica."},8:{video:"Una coorte di 888 ginocchia operate a Singapore mostra che a un anno dalla protesi solo il 42% dei pazienti riesce ad accovacciarsi e il 36% a inginocchiarsi. L'incapacità è predetta da BMI più alto, mobilità preoperatoria scarsa, poca fiducia nel ginocchio prima dell'intervento, età avanzata e sesso femminile. Un dato utile per calibrare le aspettative già nel colloquio preoperatorio, in un contesto — quello asiatico — dove questi movimenti hanno un peso culturale particolare."}};
var SOCV={1:{video:{chir:["Una revisione sistematica di 51 studi, 4.153 pazienti fino a 19 anni, guarda alla ricostruzione pediatrica del legamento crociato anteriore: innesto e tenodesi extra-articolare laterale, il LET, cambiano davvero il rischio di re-rottura in questa popolazione? Protocollo PRISMA registrato su PROSPERO, ricerca su quattro database dall'inizio ad agosto 2025, qualità valutata con il Modified Coleman Methodology Score.","Risultato: il LET si associa a re-rotture più basse con ogni innesto — hamstring 0-5,3% con LET contro 11,9-15% senza, e per la prima volta anche il tendine quadricipitale, 0% contro 7,7% senza, nei soli studi comparativi disponibili — senza compromettere il rientro allo sport, che resta fra il 42 e il 100% a seconda della definizione usata dagli autori.","Limite dichiarato: nessun RCT ha mai confrontato innesto o LET nello scheletricamente immaturo, la qualità media degli studi resta moderata — il 13,7% giudicato «poor» — e gli intervalli di confidenza non sono riportati per i confronti fra sottogruppi. È un segnale forte nella direzione della tua pratica, non ancora una dimostrazione."],misto:["Nei ragazzi operati di legamento crociato, aggiungere un piccolo rinforzo laterale durante l'intervento sembra ridurre il rischio di una nuova rottura. Lo dice una revisione molto ampia della letteratura scientifica, condotta secondo un protocollo registrato in anticipo, che ha messo insieme i risultati di 51 studi diversi su oltre 4mila pazienti fra i dieci e i diciannove anni operati al legamento crociato anteriore del ginocchio.","Il dato interessante è che il beneficio si vede con qualunque tendine sia stato usato per la ricostruzione principale — compreso il tendine quadricipitale, mai documentato prima proprio in questa fascia d'età più giovane — e senza che il ritorno allo sport ne risenta: i tempi medi di rientro restano fra sei e dodici mesi circa, secondo gli studi disponibili.","Il limite resta importante: sono quasi tutti studi osservazionali, cioè fatti guardando indietro nel tempo su pazienti già operati, non confronti randomizzati fatti apposta per rispondere a questa domanda. È un segnale coerente in tutti gli studi, non ancora una prova definitiva — ma coerente con l'indicazione che segui su ogni paziente operato."],pazienti:["Nei ragazzi operati al legamento del ginocchio, un piccolo gesto in più durante l'intervento può proteggere di più da un nuovo infortunio. Una grande revisione di studi scientifici, che ha messo insieme i risultati di 51 ricerche diverse su oltre 4mila giovani pazienti fra i dieci e i diciannove anni, ha guardato proprio a questa domanda.","Il risultato: aggiungere un rinforzo sul lato esterno del ginocchio, oltre alla ricostruzione principale del legamento, si associa a meno nuove rotture — qualunque sia il tendine usato per l'intervento — e senza rallentare il ritorno allo sport, che resta possibile nella grande maggioranza dei casi entro l'anno.","Non è ancora una certezza assoluta: gli studi disponibili non sono ancora confronti randomizzati, il tipo di prova scientifica più solido che esista, ma tutti vanno nella stessa direzione. Per un ragazzo che deve essere operato, è comunque un'informazione rassicurante da portare al colloquio con il proprio chirurgo."]},reel:{chir:["4.153 pazienti pediatrici, 51 studi: la tenodesi laterale (LET) riduce le re-rotture del LCA, ogni innesto compreso.","Per la prima volta il dato tocca anche il tendine quadricipitale: 0% di re-rottura con LET contro 7,7% senza, nei soli studi comparativi.","[testo a schermo: «LET + quadricipite: 0% vs 7,7%»] Nessun RCT ancora nello scheletricamente immaturo: segnale, non prova."],misto:["Ragazzi operati al crociato: un piccolo rinforzo laterale in più riduce le nuove rotture, in una revisione di 51 studi.","Vale con ogni tipo di innesto usato per la ricostruzione, tendine quadricipitale compreso — mai documentato prima in questa età.","[testo a schermo: «Meno re-rotture con il rinforzo laterale»] Studi osservazionali, non ancora un confronto randomizzato."],pazienti:["Un piccolo gesto in più durante l'intervento al legamento del ginocchio nei ragazzi può ridurre il rischio di una nuova rottura.","Lo mostra una revisione di 51 studi su oltre 4mila giovani pazienti, senza rallentare il ritorno allo sport.","[testo a schermo: «Meno rotture, stesso rientro allo sport»] Serve ancora conferma con studi randomizzati."]},linkedin:{chir:["LCA pediatrico: la tenodesi laterale riduce le re-rotture con ogni innesto, quadricipite compreso","Una revisione sistematica PRISMA di 51 studi (4.153 pazienti ≤19 anni, J ISAKOS, settembre 2026) valuta l'effetto combinato di innesto e tenodesi extra-articolare laterale (LET) sulla re-rottura dopo ricostruzione pediatrica del LCA.\n\nRisultato: negli studi comparativi, il LET si associa a re-rottura più bassa con ogni innesto — hamstring 0-5,3% con LET contro 11,9-15% senza; tendine quadricipitale 0% contro 7,7%, la prima volta che il dato compare in questa popolazione.","Limite dichiarato: qualità metodologica media (MCMS 58,5, 13,7% «poor»), nessun RCT ha confrontato direttamente innesto o LET nello scheletricamente immaturo, intervalli di confidenza non riportati per i sottoanalisi. È un segnale coerente con l'indicazione universale sul LET, non una dimostrazione."],misto:["Nei ragazzi operati di crociato, un piccolo rinforzo esterno riduce il rischio di una nuova rottura","Una revisione di 51 studi, oltre 4mila pazienti dai 10 ai 19 anni circa, mostra che aggiungere una tenodesi laterale alla ricostruzione del legamento crociato anteriore si associa a meno nuove rotture — con ogni tipo di tendine usato per l'innesto principale, tendine quadricipitale compreso.","Il limite resta importante: gli studi disponibili sono in gran parte retrospettivi, di qualità metodologica media, senza un confronto randomizzato diretto. Un segnale solido, non ancora una prova definitiva — ma coerente con chi, come chirurgo, sceglie di eseguire questo gesto su ogni paziente."],pazienti:["Un piccolo gesto in più che può proteggere il ginocchio dei ragazzi operati al legamento crociato","Una grande revisione di studi su oltre 4mila giovani pazienti mostra che aggiungere un piccolo rinforzo sul lato esterno del ginocchio, durante l'intervento al legamento crociato anteriore, si associa a meno nuove rotture — senza rallentare il ritorno allo sport.","Non è ancora una certezza assoluta, perché mancano confronti randomizzati diretti in questa età, ma tutti gli studi disponibili vanno nella stessa direzione."]},instagram:{chir:["🦵 LCA pediatrico: il LET funziona anche col quadricipite\n\n51 studi, 4.153 pazienti ≤19 anni.","Con la tenodesi laterale, meno re-rotture — su ogni innesto, per la prima volta anche sul tendine quadricipitale.\n\nAncora nessun RCT nello scheletricamente immaturo: segnale forte, non definitivo.","📎 Link in bio · J ISAKOS, settembre 2026"],misto:["🦵 Un piccolo gesto in più che protegge il crociato dei ragazzi\n\nUna revisione di 51 studi, oltre 4mila giovani pazienti operati al legamento crociato anteriore.","Aggiungere un rinforzo laterale sembra ridurre le nuove rotture, qualunque sia il tendine usato per la ricostruzione.\n\nServono ancora studi randomizzati per confermarlo con certezza.","📎 Link in bio"],pazienti:["🦵 Ricostruzione del crociato nei ragazzi: un rinforzo in più aiuta?\n\nUna grande revisione di studi, su oltre 4mila giovani pazienti, suggerisce di sì: meno nuove rotture, senza rallentare il ritorno allo sport.","Non è ancora una certezza definitiva, ma il segnale è coerente in tutti gli studi.","📎 Il link nella descrizione del profilo"]}},2:{video:{chir:["Nell'osteotomia tibiale alta, quanto conta correggere fino al target giusto? Una coorte di 103 ginocchia, operate da un solo chirurgo e inizialmente randomizzate a un target di correzione del 70% o del 62% della linea di carico, risponde con un follow-up radiografico e clinico fino a 10 anni — uno degli sguardi più lunghi mai pubblicati su questa domanda tecnica specifica.","Il gruppo corretto al 62% resta sotto-corretto nel 45% dei casi contro il 13% del gruppo 70% (p<0,001), e le ginocchia sotto-corrette convertono a protesi totale più spesso di quelle allineate correttamente: 36,7% contro 9,6% (p=0,012). Entrambi i gruppi perdono correzione nel tempo in modo simile, circa 5 punti percentuali in dieci anni.","Sulla conversione complessiva a protesi il confronto fra i due target originali è invece sottopotente — potenza dichiarata dagli stessi autori solo al 4,8%, ricalcolato con potenza.py: RR 0,90, IC 95% 0,44-1,81. Indicazione pratica che ne deriva: un target vicino, ma non oltre, il 70% della linea di carico sembra il compromesso più sicuro fra sovra e sotto-correzione."],misto:["Nell'intervento per raddrizzare l'asse della gamba nell'artrosi iniziale — l'osteotomia tibiale alta — quanto si corregge conta ancora dopo 10 anni. Uno studio a lungo termine su 103 ginocchia, operate tutte dallo stesso chirurgo, ha confrontato due obiettivi di correzione leggermente diversi fra loro, seguendo i pazienti fino a un decennio dopo l'intervento.","Chi viene corretto solo in parte rischia di più, nel tempo, di restare sotto-corretto rispetto all'obiettivo iniziale, e le ginocchia rimaste sotto-corrette arrivano più spesso, negli anni, a una protesi totale — quasi quattro volte più spesso di quelle corrette come previsto. Entrambi i gruppi, va detto, perdono un po' di correzione nel tempo, è un fenomeno normale dopo questo tipo di intervento.","Il confronto diretto sul rischio complessivo di protesi resta però basato su numeri piccoli, dichiarati insufficienti dagli stessi autori per una conclusione definitiva su quella domanda specifica. Il messaggio pratico che ne resta è più limitato ma solido: puntare a una correzione vicina al 70% della linea di carico, senza esagerare, sembra il compromesso più sicuro."],pazienti:["Nell'intervento per raddrizzare la gamba e alleggerire il ginocchio usurato — l'osteotomia tibiale alta — la precisione della correzione conta ancora dopo dieci anni. Uno studio a lungo termine ha seguito oltre cento pazienti operati con due diversi obiettivi di correzione, leggermente diversi fra loro, fino a dieci anni dopo l'intervento.","Uno studio a lungo termine mostra che chi riceve una correzione meno completa ha più probabilità, con gli anni, di restare con la gamba non perfettamente raddrizzata, e questo si associa a un rischio più alto di avere bisogno, in futuro, di una protesi totale di ginocchio.","Lo studio è su un numero limitato di pazienti, e sul rischio complessivo di protesi il confronto non è abbastanza forte per dare una risposta definitiva: un segnale utile per orientare la scelta chirurgica insieme al proprio medico, non ancora una regola assoluta valida per tutti."]},reel:{chir:["Osteotomia tibiale alta: target di correzione 70% vs 62% della linea di carico, 103 ginocchia, 10 anni di follow-up.","Sotto-correzione più frequente col target 62% (45% vs 13%), e più conversioni a protesi quando sotto-corretti (36,7% vs 9,6%).","[testo a schermo: «70%, non oltre»] Confronto sulla conversione globale sottopotente, dichiarato dagli autori."],misto:["Nell'osteotomia per correggere la gamba, il punto preciso della correzione conta ancora dopo 10 anni.","Chi resta sotto-corretto rischia di più, nel tempo, di arrivare a una protesi.","[testo a schermo: «Vicino al 70%, non oltre»] Numeri piccoli sul confronto diretto, dicono gli stessi autori."],pazienti:["Raddrizzare la gamba per alleggerire il ginocchio: quanto si corregge conta ancora dopo dieci anni.","Una correzione meno completa si associa, nel tempo, a più interventi di protesi.","[testo a schermo: «La precisione conta, anche a lungo termine»] Studio su un numero limitato di pazienti."]},linkedin:{chir:["Osteotomia tibiale alta: il target di correzione conta ancora a 10 anni","Una coorte di 103 ginocchia (J Exp Orthop, agosto 2026), inizialmente randomizzata a due target di correzione — 70% o 62% della linea di carico (weight-bearing line) — mostra a 10 anni che il target 62% resta sotto-corretto più spesso (45% contro 13%; p<0,001), e la sotto-correzione si associa a più conversioni a protesi totale (36,7% contro 9,6%; p=0,012).","Il confronto sulla conversione complessiva a protesi (22,0% vs 24,5%) non raggiunge la significatività ed è dichiarato sottopotente dagli stessi autori (potenza 4,8%; ricalcolato con potenza.py: RR 0,90, IC 95% 0,44-1,81). Indicazione pratica: restare vicino al 70%, senza superarlo."],misto:["Nell'osteotomia del ginocchio, la precisione della correzione conta ancora dopo dieci anni","Uno studio a lungo termine su pazienti operati di osteotomia tibiale alta — l'intervento che corregge l'asse della gamba per alleggerire il compartimento usurato — mostra che chi viene corretto solo in parte ha più probabilità, negli anni, di arrivare a una protesi totale rispetto a chi riceve una correzione più vicina al target pieno.","Il confronto diretto sul rischio di protesi resta basato su numeri contenuti, dichiarati insufficienti dagli stessi autori per una conclusione definitiva: un'indicazione tecnica utile, non ancora una regola assoluta."],pazienti:["Nell'intervento per raddrizzare la gamba, quanto si corregge conta ancora dopo dieci anni","Uno studio a lungo termine mostra che, nell'osteotomia per correggere l'asse della gamba nell'artrosi iniziale, chi riceve una correzione meno completa ha più probabilità, con gli anni, di avere bisogno di una protesi totale.","Lo studio è su un numero limitato di pazienti: un segnale utile per orientare la scelta chirurgica, non ancora una certezza assoluta."]},instagram:{chir:["🦵 Osteotomia tibiale alta: quanto conta il target di correzione?\n\n103 ginocchia, 10 anni di follow-up.","Target 62% della linea di carico: più sotto-correzione (45% vs 13%) e più conversioni a protesi (36,7% vs 9,6%).\n\nConfronto globale sulla protesi sottopotente, dicono gli stessi autori.","📎 Link in bio · J Exp Orthop, agosto 2026"],misto:["🦵 Raddrizzare la gamba: quanto si corregge conta ancora dopo 10 anni\n\nChi resta sotto-corretto nell'osteotomia tibiale rischia di più, nel tempo, di arrivare a una protesi.","Studio su un campione contenuto: segnale utile, non ancora una regola definitiva.","📎 Link in bio"],pazienti:["🦵 Intervento per raddrizzare la gamba: la precisione conta anche dopo anni\n\nUno studio a lungo termine mostra che una correzione meno completa si associa, con gli anni, a più bisogno di protesi.","Studio su un numero limitato di pazienti.","📎 Il link nella descrizione del profilo"]}},3:{video:{chir:["Nel menisco pediatrico, sutura o meniscectomia: chi protegge di più dall'artrosi post-traumatica a 10 anni? Un registro amministrativo americano su 10.352 pazienti pediatrici — 7.555 meniscectomie e 2.797 suture, seguiti almeno cinque anni, tutti sotto i 16 anni al momento dell'intervento — prova a rispondere con una scala molto più ampia del solito.","Artrosi post-traumatica a 10 anni: 1,5% dopo sutura contro 2,3% dopo meniscectomia. Ricalcolato con potenza.py sui conteggi grezzi: rischio relativo 0,65, IC 95% 0,47-0,91 — un intervallo che esclude l'assenza di differenza, a favore della sutura. Il tempo medio alla diagnosi di artrosi è leggermente più lungo nel gruppo riparato.","In entrambi i gruppi, un secondo intervento di «ripristino del movimento» per rigidità articolare è di gran lunga il fattore di rischio più forte per artrosi precoce — hazard ratio oltre 5 in entrambi i bracci. Limite di metodo: diagnosi per codice amministrativo di fatturazione, non per referto radiografico dedicato caso per caso."],misto:["Nei ragazzi con una lesione al menisco, riparare invece di asportare protegge di più dall'usura precoce del ginocchio, anche a distanza di anni. Lo mostra un grande registro amministrativo americano su oltre 10mila giovani pazienti, tutti sotto i sedici anni al momento dell'intervento, seguiti per almeno cinque anni e fino a dieci.","Il risultato: l'artrosi post-traumatica a 10 anni è più bassa dopo sutura meniscale, all'incirca 1,5 casi su 100, rispetto a dopo meniscectomia, circa 2,3 su 100 — una differenza confermata dal calcolo statistico, non solo apparente sui numeri grezzi. In entrambi i gruppi, chi ha bisogno di un secondo intervento per il ginocchio rigido dopo l'operazione è quello che rischia di più.","Il dato viene da cartelle amministrative americane, non da un esame radiografico dedicato fatto apposta su ogni paziente: un limite da tenere presente. Ma è un segnale coerente con quanto già si sapeva sulla riparazione del menisco, questa volta confermato su una scala molto più ampia del solito."],pazienti:["Nei ragazzi con il menisco lesionato, riparare protegge di più che asportare — anche molti anni dopo. Uno studio molto ampio, su oltre 10mila giovani pazienti americani sotto i sedici anni, ha confrontato che cosa succede al ginocchio a distanza di anni a seconda che il menisco sia stato riparato oppure tolto.","Il risultato: meno segni di usura precoce del ginocchio, a dieci anni di distanza, in chi ha avuto il menisco riparato invece che rimosso. La differenza è piccola in termini assoluti — pochi casi su cento in entrambi i gruppi — ma è chiara e coerente con quanto già si pensava.","È un dato che rafforza ciò che si pensava già, questa volta su un numero molto grande di ragazzi: riparare il menisco, quando è tecnicamente possibile, resta la scelta migliore per proteggere il ginocchio nel tempo, non solo nell'immediato dopo l'intervento."]},reel:{chir:["Menisco pediatrico: sutura vs meniscectomia, 10.352 pazienti, follow-up 10 anni.","Artrosi post-traumatica: 1,5% con sutura vs 2,3% con meniscectomia. RR 0,65, IC 95% 0,47-0,91.","[testo a schermo: «Riparare protegge di più, anche a 10 anni»] Diagnosi per codice amministrativo, limite di metodo."],misto:["Nei ragazzi, riparare il menisco protegge di più che asportarlo, anche dopo dieci anni.","Registro su oltre 10mila pazienti: meno segni di usura precoce del ginocchio con la sutura.","[testo a schermo: «Sutura vs meniscectomia: 1,5% vs 2,3%»] Dato da cartelle amministrative, non da RM dedicata."],pazienti:["Menisco lesionato nei ragazzi: riparare protegge di più che asportare.","Uno studio su oltre 10mila giovani pazienti conferma meno usura del ginocchio a distanza di anni.","[testo a schermo: «Riparare, quando è possibile»] Conferma un principio già noto, con un campione molto ampio."]},linkedin:{chir:["Menisco pediatrico: la sutura protegge dall'artrosi post-traumatica più della resezione, anche a 10 anni","Una coorte retrospettiva su registro amministrativo (PearlDiver, Arthrosc Sports Med Rehabil, agosto 2026), 10.352 pazienti pediatrici (7.555 meniscectomie, 2.797 suture), mostra artrosi post-traumatica a 10 anni del 2,3% dopo meniscectomia contro 1,5% dopo sutura.","Ricalcolato con potenza.py sui conteggi grezzi (42/2.797 vs 174/7.555): rischio relativo 0,65, IC 95% 0,47-0,91 — un intervallo che esclude l'assenza di differenza. In entrambi i gruppi, un secondo intervento per rigidità articolare resta il predittore più forte di artrosi precoce. Limite: diagnosi per codice di fatturazione, non per referto radiografico dedicato."],misto:["Nei ragazzi con una lesione al menisco, riparare protegge di più che asportare — anche a distanza di anni","Un ampio registro amministrativo su oltre 10mila giovani pazienti mostra che chi ha avuto il menisco riparato, invece che rimosso, sviluppa meno spesso segni di usura precoce del ginocchio a 10 anni di distanza (1,5% contro 2,3%), una differenza confermata dal calcolo statistico.","Il dato viene da cartelle amministrative, non da un esame radiografico dedicato in ogni paziente: un limite di metodo che invita a leggerlo come un segnale forte, coerente con quanto già si sapeva, non come una prova definitiva su ogni singolo caso."],pazienti:["Riparare il menisco nei ragazzi, quando è possibile, protegge di più che asportarlo","Uno studio su oltre 10mila ragazzi operati al menisco mostra che chi ha avuto il menisco riparato, anziché rimosso, ha meno probabilità di sviluppare segni di usura articolare precoce anche a distanza di dieci anni.","È un risultato che conferma un principio già noto con un campione molto ampio, non una scoperta improvvisa: riparare, quando è tecnicamente possibile, resta la scelta da preferire."]},instagram:{chir:["🦵 Menisco pediatrico: sutura o meniscectomia?\n\n10.352 pazienti, follow-up 10 anni.","Artrosi post-traumatica: 1,5% con sutura vs 2,3% con meniscectomia (RR 0,65, IC 95% 0,47-0,91).\n\nDiagnosi da codice amministrativo: limite di metodo da conoscere.","📎 Link in bio · Arthrosc Sports Med Rehabil, agosto 2026"],misto:["🦵 Nei ragazzi, riparare il menisco protegge di più che asportarlo\n\nRegistro su oltre 10mila pazienti: meno segni di usura precoce del ginocchio a 10 anni con la sutura.","Dato da cartelle amministrative, non da RM dedicata in ogni caso.","📎 Link in bio"],pazienti:["🦵 Menisco lesionato nei ragazzi: meglio riparare che asportare\n\nUno studio su oltre 10mila giovani pazienti conferma meno usura del ginocchio a distanza di anni con la riparazione.","Conferma un principio già noto, su un campione molto ampio.","📎 Il link nella descrizione del profilo"]}},4:{video:{chir:["Nella protesi totale robot-assistita, l'allineamento funzionale batte quello meccanico? Una meta-analisi di 6 studi comparativi, 645 protesi in tutto, mette a confronto le due strategie: personalizzare l'allineamento entro margini di sicurezza, oppure seguire l'asse meccanico classico uguale per tutti.","Il meccanico richiede più spesso un release aggiuntivo dei tessuti molli durante l'intervento — odds ratio 5,38 — mentre il funzionale recupera prima il movimento articolare nelle prime sei settimane. Ma a un anno il miglioramento funzionale è sovrapponibile fra i due approcci, e il Forgotten Joint Score a 6 mesi, pur migliore col funzionale, non supera la soglia di rilevanza clinica stabilita.","Solo 6 studi, 645 protesi in totale, piattaforme robotiche eterogenee, nessuna sottoanalisi per sistema specifico dichiarata nell'abstract: coerente con RACER-Knee del 21 agosto e con la revisione critica di ieri — la precisione tecnica non garantisce da sola un vantaggio che il paziente percepisce davvero nella vita di tutti i giorni."],misto:["Nella protesi di ginocchio fatta col robot, una strategia di allineamento più «su misura» per ogni paziente semplifica l'intervento — ma cambia davvero il risultato che il paziente percepisce? Una sintesi di sei studi diversi, oltre 600 protesi in totale, ha messo a confronto questa strategia personalizzata con l'allineamento tradizionale, uguale per tutti.","Il risultato: la tecnica personalizzata richiede meno gesti aggiuntivi durante l'intervento e fa recuperare il movimento un po' più in fretta nelle prime settimane. Ma dopo un anno il risultato funzionale — come il paziente sta davvero, non solo quanto si muove il ginocchio — è simile a quello della tecnica classica, senza una differenza che si possa considerare importante per la vita quotidiana.","Gli studi disponibili sono ancora pochi, solo sei, e usano sistemi robotici diversi fra loro senza distinguerli uno per uno: un quadro coerente con altri dati recenti sulla protesi robotica — la tecnologia aiuta la precisione tecnica del chirurgo, ma non garantisce da sola un vantaggio che il paziente percepisce."],pazienti:["Con la protesi robotica, una tecnica di allineamento più «su misura» per ogni paziente cambia davvero il risultato? Una revisione di più studi scientifici, che ha messo insieme i dati di oltre 600 interventi, ha provato a rispondere a questa domanda molto pratica.","Il risultato: questa tecnica più personalizzata rende l'intervento un po' più semplice per il chirurgo e il recupero iniziale del movimento un po' più veloce nelle prime settimane. Ma dopo un anno dall'intervento, il risultato per il paziente — come sta davvero il ginocchio nella vita di tutti i giorni — è simile a quello della tecnica tradizionale, ormai collaudata da anni.","Non è ancora chiaro se una tecnica sia davvero superiore all'altra sul lungo periodo: servono studi più numerosi e più lunghi per dirlo con certezza. Per ora, la scelta della tecnica di allineamento resta soprattutto una decisione del chirurgo, non un fattore che cambia da solo l'esito finale per il paziente."]},reel:{chir:["Protesi robotica: allineamento funzionale vs meccanico, 6 studi, 645 protesi.","Funzionale: meno release, recupero più rapido a 6 settimane; a 1 anno risultato funzionale simile.","[testo a schermo: «Meno release, stesso risultato a 1 anno»] Piattaforme eterogenee, nessuna sottoanalisi per sistema."],misto:["Nella protesi robotica, un allineamento più personalizzato rende l'intervento più semplice.","Ma dopo un anno il risultato funzionale è simile alla tecnica classica.","[testo a schermo: «Più semplice, non più efficace a 1 anno»] Studi ancora pochi, sistemi diversi fra loro."],pazienti:["Con la protesi robotica, una tecnica di allineamento più moderna cambia il risultato?","Rende l'intervento un po' più semplice e il recupero iniziale un po' più veloce, ma dopo un anno il risultato è simile.","[testo a schermo: «Recupero iniziale sì, risultato a 1 anno no»] Servono studi più numerosi per essere certi."]},linkedin:{chir:["Protesi robotica: l'allineamento funzionale riduce i release ma non batte il meccanico a un anno","Una meta-analisi di 6 studi comparativi (645 TKA robot-assistite, SICOT-J, settembre 2026) confronta allineamento funzionale e meccanico. Il meccanico richiede più spesso release aggiuntivo dei tessuti molli (OR 5,38; IC 95% 2,71-10,69); il funzionale recupera più movimento a 6 settimane (differenza -4,64°), differenza persa a 6 mesi.","FJS-12 a 6 mesi favorisce il funzionale (differenza -10,74) ma sotto soglia di rilevanza clinica; miglioramento funzionale a 1 anno sovrapponibile. Limite: solo 6 studi, piattaforme eterogenee, VELYS non isolato come categoria propria. Coerente con RACER-Knee (21 agosto) e con la revisione critica del 1° settembre."],misto:["Protesi robotica: un allineamento più «su misura» semplifica l'intervento, ma cambia il risultato a un anno?","Una sintesi di 6 studi su oltre 600 protesi robotiche mostra che la strategia di allineamento personalizzata richiede meno gesti aggiuntivi e fa recuperare prima il movimento, ma dopo un anno il risultato funzionale resta simile all'allineamento tradizionale.","Gli studi disponibili sono pochi e usano sistemi robotici diversi fra loro: un quadro coerente con altri dati recenti sulla protesi robotica — precisione tecnica sì, vantaggio funzionale dimostrato ancora da confermare."],pazienti:["Con la protesi robotica, una tecnica di allineamento più «su misura» cambia davvero il risultato?","Una revisione di più studi mostra che una tecnica di allineamento più personalizzata rende l'intervento un po' più semplice e il recupero iniziale un po' più veloce, ma dopo un anno il risultato è simile a quello della tecnica tradizionale.","Non è ancora chiaro se una tecnica sia davvero superiore all'altra sul lungo periodo: servono studi più numerosi e più lunghi per dirlo con certezza."]},instagram:{chir:["🦵 Protesi robotica: allineamento funzionale o meccanico?\n\n6 studi, 645 protesi.","Funzionale: meno release (OR 5,38), recupero più rapido a 6 settimane.\n\nA 1 anno: risultato funzionale simile.","Coerente con RACER-Knee: precisione sì, vantaggio percepito ancora da provare.\n\n📎 Link in bio · SICOT-J, settembre 2026"],misto:["🦵 Protesi robotica: un allineamento più personalizzato conta davvero?\n\nMeno gesti aggiuntivi, recupero iniziale più veloce — ma a 1 anno il risultato è simile alla tecnica classica.","Studi ancora pochi, sistemi diversi fra loro.","📎 Link in bio"],pazienti:["🦵 Con la protesi robotica, l'allineamento «su misura» cambia il risultato?\n\nRecupero iniziale un po' più veloce, ma dopo un anno il risultato è simile alla tecnica classica.","Servono ancora studi più numerosi.","📎 Il link nella descrizione del profilo"]}},5:{video:{chir:["Protesi d'anca e ginocchio in pazienti già in anticoagulazione cronica: come si bilancia rischio trombotico e rischio emorragico? Una rassegna multidisciplinare — chirurgia ortopedica, medicina ospedaliera, farmacia clinica — fa il punto sullo stato dell'arte.","Stratificazione del rischio paziente-specifica, scelta dell'agente tromboprofilattico più adatto, gestione perioperatoria di anticoagulanti e antiaggreganti cronici, coordinamento fra le figure coinvolte nel percorso del paziente: un lavoro di squadra fra chirurgo, internista, anestesista e farmacista clinico, non un protocollo lasciato al solo chirurgo.","È una revisione narrativa, senza sintesi quantitativa propria e senza dati originali: raccoglie e organizza raccomandazioni già esistenti in letteratura, utile soprattutto come guida pratica di riferimento per ogni lista operatoria con pazienti complessi, in politerapia o con più patologie associate."],misto:["Come si gestiscono, prima e dopo una protesi di anca o ginocchio, i farmaci che fluidificano il sangue? È una domanda sempre più frequente, perché sempre più pazienti candidati a una protesi assumono già un anticoagulante per altre ragioni cliniche.","Una rassegna scritta insieme da chirurghi, internisti e farmacisti spiega come bilanciare il rischio di trombosi — una complicanza nota dopo protesi articolare — con quello di sanguinamento durante e dopo l'intervento, costruendo un piano su misura per ogni singolo paziente invece di applicare un protocollo uguale per tutti.","È una guida pratica basata su raccomandazioni già esistenti, non uno studio con dati clinici originali — ma resta utile per capire, in modo semplice, come viene gestito oggi questo aspetto delicato e sempre più comune dell'intervento di protesi."],pazienti:["Se prendi farmaci per fluidificare il sangue e devi fare una protesi di ginocchio o d'anca, ecco come si gestisce in sicurezza questo aspetto dell'intervento, sempre più frequente con l'età che avanza.","Una rassegna scritta da un gruppo di specialisti — chirurgo, internista, farmacista — spiega come vengono bilanciati, prima e dopo l'intervento, il rischio di trombosi e quello di sanguinamento nei pazienti che già assumono questi farmaci per altre ragioni di salute.","È una guida pratica, non una nuova scoperta scientifica: serve a rendere più sicuro un percorso che riguarda sempre più pazienti anziani o con più malattie insieme, costruendo un piano pensato apposta per la loro situazione."]},reel:{chir:["Protesi e anticoagulazione cronica: come si bilancia trombosi e sanguinamento?","Stratificazione del rischio, scelta dell'agente, gestione perioperatoria: lavoro di squadra multidisciplinare.","[testo a schermo: «Rischio su misura, non protocollo uguale per tutti»] Revisione narrativa di raccomandazioni esistenti."],misto:["Come si gestiscono i farmaci per il sangue prima di una protesi?","Un piano su misura per ogni paziente, non un protocollo uguale per tutti.","[testo a schermo: «Trombosi e sanguinamento, in equilibrio»] Guida pratica, non uno studio con dati nuovi."],pazienti:["Prendi farmaci per il sangue e devi fare una protesi? Ecco come si gestisce.","Un piano su misura bilancia il rischio di trombosi e quello di sanguinamento.","[testo a schermo: «Un percorso pensato per te»] Guida pratica per un percorso più sicuro."]},linkedin:{chir:["Protesi d'anca e ginocchio: una rassegna pratica su anticoagulanti e tromboprofilassi","Una revisione narrativa multidisciplinare (Clin Appl Thromb Hemost, settembre 2026 — chirurgia, medicina ospedaliera, farmacia clinica) riassume come stratificare il rischio tromboembolico ed emorragico e come gestire nel perioperatorio anticoagulanti e antiaggreganti cronici in protesi totale di anca e ginocchio.","Nessuna sintesi quantitativa propria: è una rassegna di raccomandazioni esistenti, con un messaggio pratico chiaro — un regime costruito sul singolo paziente, con un team multidisciplinare, bilancia meglio rischio trombotico ed emorragico di un protocollo uniforme."],misto:["Come si gestiscono gli anticoagulanti prima e dopo una protesi di anca o ginocchio","Una rassegna scritta da chirurghi, internisti e farmacisti spiega come bilanciare il rischio di trombosi con quello di sanguinamento nei pazienti che assumono farmaci anticoagulanti e devono essere operati di protesi, con un piano costruito caso per caso.","È una rassegna di raccomandazioni già esistenti, non uno studio con dati originali: utile come guida pratica per un aspetto dell'intervento che riguarda sempre più pazienti, con più patologie associate e più farmaci in corso."],pazienti:["Se prendi farmaci per il sangue e devi fare una protesi, ecco come si gestisce in sicurezza","Una rassegna scritta da un gruppo di specialisti spiega come vengono gestiti, prima e dopo l'intervento di protesi, i farmaci che fluidificano il sangue, per ridurre sia il rischio di trombosi sia quello di sanguinamento.","È una guida pratica basata su raccomandazioni esistenti, pensata per rendere più sicuro il percorso di chi già assume questi farmaci prima di un intervento."]},instagram:{chir:["🩸 Protesi e anticoagulazione cronica: come si bilancia il rischio?\n\nStratificazione del rischio, scelta dell'agente, gestione perioperatoria.","Un lavoro di squadra: chirurgo, internista, farmacista clinico.\n\nRassegna di raccomandazioni esistenti, non nuovi dati.","📎 Link in bio · Clin Appl Thromb Hemost, settembre 2026"],misto:["🩸 Farmaci per il sangue e protesi: come si gestiscono insieme?\n\nUn piano su misura per ogni paziente bilancia trombosi e sanguinamento.","Guida pratica per chirurghi e medici di famiglia.","📎 Link in bio"],pazienti:["🩸 Prendi farmaci per il sangue e devi fare una protesi?\n\nEcco come si bilancia, in sicurezza, il rischio di trombosi e quello di sanguinamento.","Una guida pratica per un percorso più sicuro.","📎 Il link nella descrizione del profilo"]}},6:{video:{chir:["Dopo la rottura del LCA, quali fattori si legano a un danno cartilagineo più esteso al momento della ricostruzione? Una coorte retrospettiva monocentrica cinese di 80 pazienti con rottura primaria unilaterale, danno classificato con il sistema ICRS su RM e valutazione artroscopica, indaga la domanda con una regressione logistica multivariabile.","BMI più alto, intervallo trauma-chirurgia più lungo e lesioni meniscali sia mediali sia laterali restano indipendentemente associati al danno cartilagineo all'analisi multivariabile; età ed edema osseo o contusione ossea non risultano predittori indipendenti in questa coorte, a differenza di quanto ci si potrebbe aspettare.","Campione modesto — 80 pazienti, 32 con danno cartilagineo concomitante — e gli stessi autori definiscono i risultati esplorativi e generatori di ipotesi, da confermare in coorti più ampie prima di cambiare la pratica clinica basandosi su questo solo dato."],misto:["Aspettare troppo dopo la rottura del legamento crociato, o arrivare all'intervento con un peso corporeo più alto, può costare caro alla cartilagine del ginocchio. Uno studio retrospettivo condotto in Cina su 80 pazienti operati di ricostruzione del legamento crociato anteriore ha guardato proprio a questa domanda.","Il risultato: chi arriva alla ricostruzione con un'attesa più lunga dal trauma, un indice di massa corporea più alto, oppure con il menisco già lesionato su entrambi i lati del ginocchio, ha più probabilità di avere anche un danno alla cartilagine al momento dell'intervento — un danno visto sia alla risonanza sia direttamente in artroscopia.","Il campione è piccolo, appena 80 pazienti, e gli stessi autori descrivono lo studio come esplorativo, non definitivo. È comunque un segnale da confermare in studi più ampi, coerente con l'idea generale di non rimandare l'intervento senza una ragione clinica precisa."],pazienti:["Dopo la rottura del legamento del ginocchio, non conviene aspettare troppo per operarsi. Uno studio condotto in Cina su 80 pazienti ha guardato a che cosa succede alla cartilagine del ginocchio quando l'intervento arriva dopo un'attesa più lunga del solito.","Il risultato: chi si opera dopo un'attesa più lunga, o ha un peso corporeo più alto, o ha già una lesione al menisco, arriva più spesso all'intervento con un danno anche alla cartilagine — non solo al legamento rotto — visibile sia alla risonanza magnetica sia durante l'operazione stessa.","È uno studio su un numero limitato di pazienti, descritto dagli stessi autori come preliminare: un motivo in più, non una certezza assoluta, per non rimandare l'intervento senza una ragione clinica precisa, quando le condizioni lo permettono."]},reel:{chir:["LCA: BMI, ritardo chirurgico e lesioni meniscali predicono il danno cartilagineo, 80 pazienti.","Analisi multivariabile: tutti e tre restano fattori indipendenti; età e edema osseo no.","[testo a schermo: «Non aspettare, non sovrappeso: meno danno cartilagineo»] Campione piccolo, risultati esplorativi."],misto:["Aspettare troppo dopo la rottura del crociato può costare caro alla cartilagine.","Peso corporeo più alto e attesa più lunga si legano a un danno cartilagineo maggiore al momento dell'intervento.","[testo a schermo: «Meglio non rimandare»] Studio piccolo, dichiarato esplorativo dagli autori."],pazienti:["Dopo la rottura del legamento del ginocchio, non conviene aspettare troppo per operarsi.","Chi si opera dopo un'attesa più lunga arriva più spesso all'intervento con un danno anche alla cartilagine.","[testo a schermo: «Prima ti operi, meglio è per la cartilagine»] Studio su un numero limitato di pazienti."]},linkedin:{chir:["Dopo la rottura del LCA, BMI e ritardo chirurgico si legano al danno cartilagineo","Una coorte retrospettiva monocentrica (80 pazienti, Medicine, agosto 2026) mostra che BMI più alto, intervallo trauma-chirurgia più lungo e lesioni meniscali sia mediali sia laterali restano indipendentemente associati a danno cartilagineo (ICRS ≥2) al momento della ricostruzione del LCA; età ed edema osseo non risultano predittori indipendenti.","Limite dichiarato dagli stessi autori: campione modesto (32/80 con danno cartilagineo), risultati esplorativi e generatori di ipotesi, da confermare in coorti più ampie. Un motivo tecnico in più per non allungare i tempi fra infortunio e ricostruzione quando la situazione clinica lo consente."],misto:["Aspettare troppo dopo la rottura del crociato può costare caro alla cartilagine","Uno studio retrospettivo su 80 pazienti mostra che chi arriva all'intervento con un peso corporeo più alto, dopo un'attesa più lunga o con il menisco già lesionato ha più probabilità di avere anche un danno alla cartilagine del ginocchio al momento della ricostruzione del legamento crociato.","Il campione è piccolo e lo studio viene descritto dagli stessi autori come esplorativo: un segnale da confermare, non una regola definitiva — ma coerente con il principio di non rimandare l'intervento senza una ragione clinica precisa."],pazienti:["Dopo la rottura del legamento del ginocchio, non conviene aspettare troppo per operarsi","Uno studio mostra che chi si opera dopo un'attesa più lunga, o ha un peso corporeo più alto, o ha già una lesione al menisco, arriva più spesso all'intervento con un danno anche alla cartilagine del ginocchio.","È uno studio su un numero limitato di pazienti, descritto dagli stessi autori come preliminare: un motivo in più, non una certezza assoluta, per non rimandare l'intervento senza necessità."]},instagram:{chir:["🦵 LCA: cosa predice il danno cartilagineo al momento dell'intervento?\n\n80 pazienti, analisi multivariabile.","BMI più alto, attesa più lunga, lesioni meniscali: tutti fattori indipendenti.\n\nCampione modesto, risultati esplorativi dichiarati dagli autori.","📎 Link in bio · Medicine, agosto 2026"],misto:["🦵 Aspettare troppo dopo la rottura del crociato può costare caro alla cartilagine\n\nPeso corporeo più alto e attesa più lunga si legano a un danno maggiore al momento dell'intervento.","Studio piccolo, dichiarato esplorativo.","📎 Link in bio"],pazienti:["🦵 Rottura del legamento del ginocchio: meglio non aspettare troppo\n\nChi si opera dopo un'attesa più lunga arriva più spesso con un danno anche alla cartilagine.","Studio su un numero limitato di pazienti.","📎 Il link nella descrizione del profilo"]}},7:{video:{chir:["Una ricostruzione RM assistita da intelligenza artificiale migliora la diagnosi delle lesioni del LCP? Uno studio diagnostico retrospettivo su 110 pazienti, con lesione del legamento crociato posteriore confermata artroscopicamente, confronta la ricostruzione standard con un algoritmo dedicato, in doppio cieco fra due radiologi.","Qualità dell'immagine nettamente superiore su tutti i parametri soggettivi e oggettivi misurati, accordo interosservatore da buono a eccellente (kappa pesato 0,63-0,97). Sulle lesioni complete, di grado 3, l'accuratezza diagnostica è buona, area sotto la curva 0,79; su quelle parziali, di grado 1 e 2, resta debole, area sotto la curva rispettivamente 0,54 e 0,17.","L'intelligenza artificiale qui aiuta soprattutto la qualità dell'immagine, non ancora la diagnosi più difficile: una lesione parziale letta come tale alla risonanza va comunque confermata in artroscopia, esattamente come prima di questa tecnologia — l'accordo complessivo fra risonanza e artroscopia resta solo moderato, kappa 0,57."],misto:["Una risonanza magnetica «più intelligente», elaborata con un algoritmo di intelligenza artificiale, può aiutare a leggere meglio il legamento crociato posteriore del ginocchio, uno dei due legamenti principali che stabilizzano l'articolazione. Uno studio su 110 pazienti, confrontato con l'esame più affidabile che esiste — l'artroscopia — ha messo alla prova questa tecnologia.","Il risultato è a due facce: la qualità dell'immagine migliora nettamente, e i radiologi riconoscono molto bene le rotture complete del legamento, quelle più gravi. Ma quando la lesione è solo parziale, la tecnologia resta molto meno affidabile, quasi quanto indovinare, per il grado più lieve.","Per le lesioni parziali resta quindi comunque necessaria una valutazione clinica o artroscopica più approfondita: questa tecnologia aiuta a vedere meglio l'immagine, ma non sostituisce ancora il giudizio clinico nei casi più difficili da interpretare, che restano la maggioranza in pratica quotidiana."],pazienti:["Una risonanza magnetica più avanzata, aiutata dall'intelligenza artificiale, aiuta a vedere meglio le rotture di uno dei legamenti dietro al ginocchio. Uno studio su 110 pazienti ha confrontato questa nuova tecnica con l'esame più affidabile per questo tipo di lesione, fatto direttamente durante un piccolo intervento chirurgico.","Il risultato: questa tecnica più moderna permette di vedere meglio le rotture complete del legamento, quelle più gravi e nette. Ma quando la lesione è solo parziale, cioè non del tutto rotta, la tecnica diventa molto meno precisa e affidabile, anche se l'immagine appare più chiara.","Per le lesioni parziali resta quindi comunque necessaria una valutazione più approfondita da parte del medico: questa tecnologia aiuta a vedere meglio l'immagine, ma non sostituisce il giudizio clinico nei casi più difficili da interpretare."]},reel:{chir:["LCP: ricostruzione RM con IA, 110 pazienti, standard artroscopico.","AUC 0,79 sulle lesioni complete; solo 0,54 e 0,17 sulle parziali.","[testo a schermo: «Meglio l'immagine, non ancora la diagnosi difficile»] Le parziali restano da confermare in artroscopia."],misto:["Una risonanza più «intelligente» aiuta a vedere meglio il legamento dietro al ginocchio.","Bene sulle rotture complete, meno bene su quelle parziali.","[testo a schermo: «Più chiara l'immagine, non ancora la diagnosi difficile»] Serve sempre conferma clinica sulle parziali."],pazienti:["Una risonanza più avanzata aiuta a vedere meglio un legamento del ginocchio.","Funziona bene per le rotture nette, meno per quelle parziali.","[testo a schermo: «Aiuta, non sostituisce il medico»] Per le lesioni parziali serve sempre una valutazione in più."]},linkedin:{chir:["LCP: una ricostruzione RM più rapida legge bene le lesioni complete, meno le parziali","Uno studio diagnostico retrospettivo (110 pazienti, standard artroscopico, Medicine, agosto 2026) confronta la ricostruzione RM standard con un algoritmo di intelligenza artificiale (IQMR) per il grading delle lesioni del legamento crociato posteriore (LCP).","Qualità d'immagine significativamente superiore (p<0,005), accordo interosservatore buono-eccellente (kappa 0,63-0,97). Accuratezza vs artroscopia: AUC 0,79 per le lesioni complete, ma solo 0,54 e 0,17 per le parziali di grado 1 e 2. Un promemoria: la lesione parziale letta come tale alla RM va comunque confermata in artroscopia."],misto:["Una risonanza magnetica «più intelligente» aiuta a leggere meglio uno dei legamenti del ginocchio","Uno studio su 110 pazienti, confrontato con l'artroscopia, mostra che un nuovo metodo di elaborazione delle immagini di risonanza, assistito da intelligenza artificiale, migliora la qualità dell'immagine e riconosce bene le rotture complete del legamento crociato posteriore, ma resta meno affidabile sulle lesioni parziali.","Per le lesioni parziali, le più difficili da inquadrare anche per un radiologo esperto, resta necessaria una valutazione clinica o artroscopica più approfondita: la tecnologia qui aiuta la qualità dell'immagine, non sostituisce ancora il giudizio clinico sui casi complessi."],pazienti:["Una risonanza più avanzata aiuta a vedere meglio le rotture di un legamento del ginocchio","Uno studio mostra che una tecnica più moderna di elaborazione delle immagini di risonanza magnetica, aiutata dall'intelligenza artificiale, permette di vedere meglio le rotture complete di uno dei legamenti dietro al ginocchio, ma è meno precisa quando la lesione è solo parziale.","Per le lesioni parziali resta comunque necessaria una valutazione più approfondita: questa tecnologia aiuta a vedere meglio, ma non sostituisce il giudizio clinico nei casi più difficili."]},instagram:{chir:["🦵 LCP: la RM con IA migliora la diagnosi?\n\n110 pazienti, standard artroscopico.","AUC 0,79 su lesioni complete, solo 0,54-0,17 su quelle parziali.\n\nUtile per l'immagine, non ancora per la diagnosi difficile.","📎 Link in bio · Medicine, agosto 2026"],misto:["🦵 Una risonanza più «intelligente» per il legamento dietro al ginocchio\n\nBuona sulle rotture complete, meno affidabile su quelle parziali.","Serve sempre conferma clinica per le lesioni parziali.","📎 Link in bio"],pazienti:["🦵 Una risonanza più avanzata per vedere meglio un legamento del ginocchio\n\nFunziona bene sulle rotture nette, meno su quelle parziali.","Aiuta il medico, non lo sostituisce.","📎 Il link nella descrizione del profilo"]}},8:{video:{chir:["A un anno dalla protesi di ginocchio, quanti pazienti riescono davvero a inginocchiarsi o accovacciarsi? Una coorte retrospettiva monocentrica di 888 ginocchia in 830 pazienti a Singapore, con modelli predittivi uni e multivariabili sui fattori pre-, intra- e postoperatori, misura il dato reale invece di darlo per scontato.","A un anno: 42% riesce ad accovacciarsi, 36% a inginocchiarsi, 30% entrambe le cose — con tassi di incapacità speculari, 58%, 64% e 70%. L'incapacità è predetta in modo indipendente da BMI più alto, ROM e flessione preoperatori scarsi, poca fiducia preoperatoria nel ginocchio misurata con l'Oxford Knee Score, età avanzata e sesso femminile, tutti fattori con p<0,05.","Monocentrico, popolazione del Sud-Est asiatico dove la posizione accovacciata ha un peso culturale specifico nella vita quotidiana: la trasferibilità esatta dei numeri al tuo contesto va verificata, ma il messaggio di fondo sulle aspettative preoperatorie resta valido ovunque tu operi."],misto:["Dopo la protesi di ginocchio, molti pazienti si aspettano di tornare a inginocchiarsi o stare accovacciati come facevano prima dell'intervento — ma quanti ci riescono davvero, un anno dopo? Uno studio condotto a Singapore su quasi 900 ginocchia operate ha misurato il dato reale, invece di darlo per scontato nel colloquio preoperatorio.","Il risultato: a un anno solo 4 pazienti su 10 riescono ad accovacciarsi comodamente e poco più di 1 su 3 a inginocchiarsi; contano soprattutto il peso corporeo, la mobilità del ginocchio prima dell'intervento e quanto ci si fidava già del proprio ginocchio prima di essere operati — più di quanto conti la tecnica chirurgica scelta.","È uno studio su una sola popolazione, quella di Singapore, dove questi movimenti hanno un peso culturale particolare nella vita di tutti i giorni. Ma il messaggio pratico vale in generale: le aspettative su questi movimenti vanno costruite prima dell'intervento, con dati reali alla mano, non lasciate all'immaginazione del paziente."],pazienti:["Dopo la protesi, inginocchiarsi o stare accovacciati resta difficile per molti pazienti: meglio saperlo prima di operarsi, per non restare delusi dopo. Uno studio condotto a Singapore su quasi 900 ginocchia operate ha misurato con precisione quanti pazienti ci riescono davvero, un anno dopo l'intervento.","Il risultato: circa due pazienti su tre non riescono più, a un anno dalla protesi, a inginocchiarsi o accovacciarsi con sicurezza e senza fastidio — soprattutto chi arrivava all'intervento con un ginocchio già molto rigido, o poco fiducioso nei propri movimenti già prima di operarsi.","Conoscerlo prima dell'intervento aiuta a costruire aspettative realistiche insieme al proprio chirurgo, senza promesse che l'intervento da solo non può mantenere, e magari a lavorare sulla mobilità del ginocchio già nelle settimane prima di operarsi."]},reel:{chir:["Protesi di ginocchio: chi riesce davvero a inginocchiarsi o accovacciarsi a 1 anno? 888 ginocchia, Singapore.","42% accovacciarsi, 36% inginocchiarsi, 30% entrambe. Predittori: BMI, ROM preop, fiducia preop, età, sesso.","[testo a schermo: «2 pazienti su 3 non ci riescono»] Monocentrico, popolazione del Sud-Est asiatico."],misto:["Dopo la protesi, quanti riescono davvero a inginocchiarsi o stare accovacciati?","Solo 4 su 10 si accovacciano, poco più di 1 su 3 si inginocchia, a un anno.","[testo a schermo: «Le aspettative vanno costruite prima»] Conta il ginocchio di partenza, non solo la tecnica."],pazienti:["Dopo la protesi, inginocchiarsi o stare accovacciati resta difficile per molti.","Uno studio su quasi 900 pazienti lo conferma: meglio saperlo prima dell'intervento.","[testo a schermo: «Aspettative realistiche, fin dall'inizio»] Conta come sta il ginocchio prima di operarsi."]},linkedin:{chir:["Dopo la protesi, due pazienti su tre non riescono a inginocchiarsi o accovacciarsi","Una coorte retrospettiva monocentrica (888 ginocchia/830 pazienti, Singapore, J Arthroplasty, settembre 2026) misura la capacità di inginocchiarsi e accovacciarsi a 1 anno da protesi primaria: 42% accovacciarsi, 36% inginocchiarsi, 30% entrambe.","L'incapacità è predetta in modo indipendente da BMI più alto, ROM e flessione preoperatori scarsi, poca fiducia preoperatoria (OKS domanda 4), età avanzata e sesso femminile (tutti p<0,05). Monocentrico, popolazione del Sud-Est asiatico dove questi movimenti hanno un peso culturale specifico: trasferibilità da verificare, messaggio pratico valido in generale."],misto:["Dopo la protesi di ginocchio, inginocchiarsi e accovacciarsi restano difficili per molti pazienti","Uno studio su quasi 900 ginocchia operate mostra che a un anno dall'intervento solo 4 pazienti su 10 riescono ad accovacciarsi e poco più di 1 su 3 a inginocchiarsi; il peso corporeo, la mobilità di partenza e quanto il paziente si fidava del proprio ginocchio prima dell'intervento sono i fattori che contano di più.","È uno studio su una sola popolazione (Singapore), non generalizzabile senza cautela a ogni contesto culturale — ma utile per costruire aspettative realistiche già nel colloquio preoperatorio, prima ancora di scegliere la tecnica."],pazienti:["Dopo la protesi, inginocchiarsi o stare accovacciati resta difficile per molti: meglio saperlo prima","Uno studio su quasi 900 pazienti operati mostra che circa due su tre non riescono più, a un anno dalla protesi, a inginocchiarsi o accovacciarsi con sicurezza — soprattutto chi arrivava all'intervento con un ginocchio già molto rigido o poco fiducioso nei suoi movimenti.","Conoscerlo prima dell'intervento aiuta a costruire aspettative realistiche, senza promesse che l'intervento da solo non può mantenere, e a lavorare sulla mobilità già prima di operarsi."]},instagram:{chir:["🦵 Protesi di ginocchio: chi riesce davvero a inginocchiarsi o accovacciarsi?\n\n888 ginocchia, Singapore, follow-up 1 anno.","42% accovacciarsi, 36% inginocchiarsi, 30% entrambe.\n\nPredittori: BMI, ROM preoperatorio, fiducia nel ginocchio, età, sesso.","📎 Link in bio · J Arthroplasty, settembre 2026"],misto:["🦵 Dopo la protesi, inginocchiarsi e accovacciarsi restano difficili per molti\n\nSolo 4 pazienti su 10 si accovacciano, poco più di 1 su 3 si inginocchia, a 1 anno.","Contano peso corporeo, mobilità di partenza e fiducia nel ginocchio.","📎 Link in bio"],pazienti:["🦵 Dopo la protesi, inginocchiarsi o stare accovacciati resta difficile per molti\n\nMeglio saperlo prima: aspettative realistiche fin dal colloquio preoperatorio.","Conta come sta il ginocchio prima di operarsi.","📎 Il link nella descrizione del profilo"]}}};
var TAGS={1:{linkedin:"#ACLReconstruction #Pediatric #LET",instagram:"#LCA #Ginocchio #ChirurgiaOrtopedica #LET #Adolescenti #SportInfortuni #CrociatoAnteriore #Ortopedia #MedicinaSportiva",kw:"ricostruzione LCA ragazzi · tenodesi laterale ginocchio"},2:{linkedin:"#HTO #Osteotomia #Ortopedia",instagram:"#Osteotomia #Ginocchio #ArtrosiPrecoce #ChirurgiaOrtopedica #Ortopedia #Medicina #SaluteArticolare #HTO #ChirurgiaGinocchio",kw:"osteotomia tibiale alta · correzione asse gamba"},3:{linkedin:"#Meniscus #Pediatric #KneeSurgery",instagram:"#Menisco #Ginocchio #ChirurgiaOrtopedica #Adolescenti #SuturaMeniscale #Ortopedia #SportInfortuni #SaluteArticolare #Pediatria",kw:"sutura menisco ragazzi · meniscectomia adolescenti"},4:{linkedin:"#TKA #RoboticSurgery #JointReplacement",instagram:"#ProtesiGinocchio #ChirurgiaRobotica #TKA #Ortopedia #ChirurgiaOrtopedica #Ginocchio #SaluteArticolare #Robotica #Medicina",kw:"allineamento protesi robotica · TKA funzionale meccanico"},5:{linkedin:"#Arthroplasty #VTE #Anticoagulation",instagram:"#ProtesiTotale #Trombosi #Anticoagulanti #ChirurgiaOrtopedica #Ortopedia #SaluteArticolare #Medicina #Prevenzione #Chirurgia",kw:"anticoagulanti protesi ginocchio · trombosi dopo protesi"},6:{linkedin:"#ACL #CartilageInjury #SportsMedicine",instagram:"#LCA #Cartilagine #Ginocchio #ChirurgiaOrtopedica #Ortopedia #MedicinaSportiva #SaluteArticolare #Infortuni #Ortopedico",kw:"rottura crociato tempi intervento · danno cartilagine ginocchio"},7:{linkedin:"#PCL #MRI #ArtificialIntelligence",instagram:"#LCP #RisonanzaMagnetica #IntelligenzaArtificiale #Ginocchio #ChirurgiaOrtopedica #Ortopedia #Radiologia #Diagnostica #Medicina",kw:"lesione legamento crociato posteriore · risonanza ginocchio intelligenza artificiale"},8:{linkedin:"#TKA #PatientOutcomes #Arthroplasty",instagram:"#ProtesiGinocchio #Riabilitazione #ChirurgiaOrtopedica #Ortopedia #Ginocchio #SaluteArticolare #Recupero #Aspettative #Chirurgia",kw:"inginocchiarsi dopo protesi · accovacciarsi protesi ginocchio"}};
var NLB={1:{prof:["LCA pediatrico: la tenodesi laterale riduce le re-rotture con ogni tipo di innesto","Una revisione sistematica di 51 studi (4.153 pazienti ≤19 anni) mostra che aggiungere una tenodesi extra-articolare laterale (LET) alla ricostruzione del LCA si associa a re-rotture più basse con ogni innesto, hamstring e tendine quadricipitale compresi, senza compromettere il rientro allo sport.","Nessun RCT ha ancora confrontato direttamente innesto o LET nello scheletricamente immaturo: la base resta fatta di serie retrospettive di qualità moderata."],mix:["Nei ragazzi operati di crociato, il rinforzo laterale sembra ridurre il rischio di una nuova rottura","Un'ampia revisione della letteratura su oltre 4mila adolescenti operati di legamento crociato anteriore mostra che aggiungere un piccolo gesto di rinforzo sul lato esterno del ginocchio (la tenodesi laterale) si associa a meno nuove rotture, qualunque sia il tendine usato per la ricostruzione.","Il limite è importante: gli studi disponibili sono quasi tutti osservazionali, senza un confronto randomizzato diretto, quindi il risultato è un segnale forte ma non ancora una prova definitiva."],paz:["Dopo l'intervento al legamento crociato nei ragazzi, un piccolo gesto in più può proteggere di più","Una revisione di molti studi su ragazzi e adolescenti operati al legamento crociato del ginocchio mostra che aggiungere un piccolo rinforzo esterno durante l'intervento sembra ridurre il rischio di una nuova rottura, senza rallentare il ritorno allo sport.","Non è ancora una certezza assoluta: servono studi di qualità più alta per confermarlo con sicurezza."],kw:"LCA adolescenti · rinforzo laterale ginocchio"},2:{prof:["Osteotomia tibiale alta: il target di correzione al 70% resiste meglio a 10 anni","Una coorte di 103 ginocchia, inizialmente randomizzate a due target di correzione (70% o 62% della linea di carico), mostra a 10 anni che il target 62% resta più spesso sotto-corretto (45% contro 13%) e che la sotto-correzione si associa a più conversioni a protesi (36,7% contro 9,6%; p=0,012).","Il confronto sulla conversione complessiva a protesi non raggiunge la significatività ed è dichiarato sottopotente dagli stessi autori (potenza 4,8%)."],mix:["Nell'osteotomia del ginocchio, correggere fino al punto giusto conta ancora dopo 10 anni","Uno studio a lungo termine su pazienti operati di osteotomia tibiale (la correzione dell'asse della gamba per alleggerire il compartimento usurato) mostra che chi viene corretto solo parzialmente rischia di più di arrivare, negli anni, a una protesi totale.","È uno studio con un campione limitato, e il confronto principale sul rischio di protesi è dichiarato dagli stessi autori troppo piccolo per essere conclusivo."],paz:["Nell'intervento per raddrizzare la gamba, la precisione della correzione conta ancora dopo dieci anni","Uno studio a lungo termine mostra che, nell'intervento per correggere l'asse della gamba nell'artrosi iniziale, correggere abbastanza fa la differenza: chi resta corretto solo in parte ha più probabilità, negli anni, di aver bisogno di una protesi.","Lo studio è su un numero limitato di pazienti, quindi il dato va confermato da ricerche più ampie."],kw:"osteotomia ginocchio · correzione asse gamba"},3:{prof:["Menisco nei ragazzi: riparare protegge dall'artrosi post-traumatica più che asportare","Un registro amministrativo di oltre 10.000 pazienti pediatrici mostra che a 10 anni l'artrosi post-traumatica è meno frequente dopo sutura meniscale che dopo meniscectomia (1,5% contro 2,3%; rischio relativo 0,65, IC 95% 0,47-0,91).","Diagnosi per codice di fatturazione amministrativo, non per referto radiografico standardizzato: un limite di metodo da tenere presente."],mix:["Nei ragazzi con un menisco lesionato, riparare protegge di più che asportare, anche a distanza di anni","Un grande registro americano su oltre 10mila giovani pazienti mostra che chi ha avuto il menisco riparato, invece che asportato, sviluppa meno spesso segni di artrosi precoce a 10 anni di distanza.","Il dato viene da cartelle amministrative, non da un esame radiografico dedicato: un limite che invita a leggerlo come un segnale forte, non come una certezza assoluta."],paz:["Riparare il menisco nei ragazzi, quando è possibile, protegge di più che asportarlo","Uno studio su molti ragazzi operati al menisco mostra che chi ha avuto il menisco riparato, anziché rimosso, ha meno probabilità di sviluppare segni di usura articolare precoce anni dopo.","È un risultato che rafforza un principio già noto, non una scoperta improvvisa: riparare, quando è possibile, resta la scelta migliore."],kw:"menisco ragazzi · sutura meniscale"},4:{prof:["Protesi robotica: l'allineamento funzionale riduce i release ma non batte il classico a un anno","Una meta-analisi di 6 studi comparativi (645 protesi) mostra che l'allineamento funzionale richiede meno release dei tessuti molli (OR 5,38 a favore del meccanico che ne richiede di più) e recupera prima il movimento, ma a un anno il miglioramento funzionale è sovrapponibile all'allineamento meccanico classico.","Solo 6 studi in tutto, piattaforme robotiche eterogenee: nessuna sottoanalisi per sistema specifico dichiarata nell'abstract."],mix:["Nella protesi fatta col robot, un allineamento più «su misura» semplifica l'intervento ma non cambia il risultato a un anno","Una sintesi di 6 studi su oltre 600 protesi robotiche mostra che la strategia di allineamento più personalizzata richiede meno gesti aggiuntivi durante l'intervento e fa recuperare il movimento un po' prima, ma dopo un anno il risultato funzionale è simile all'allineamento tradizionale.","Gli studi disponibili sono ancora pochi e usano sistemi robotici diversi fra loro, quindi il confronto non distingue fra le varie piattaforme."],paz:["Con la protesi robotica, la tecnica di allineamento più moderna non cambia il risultato dopo un anno","Una revisione di più studi sulla protesi di ginocchio fatta con l'aiuto del robot mostra che una tecnica di allineamento più «su misura» per ogni paziente rende l'intervento un po' più semplice e il recupero iniziale un po' più veloce, ma dopo un anno il risultato è simile a quello della tecnica classica.","Non è ancora chiaro se una tecnica sia davvero superiore all'altra: servono studi più numerosi."],kw:"protesi ginocchio robot · allineamento protesi"},5:{prof:["Protesi d'anca e ginocchio: una rassegna pratica su anticoagulanti e tromboprofilassi","Una revisione narrativa multidisciplinare riassume come stratificare il rischio tromboembolico ed emorragico e come gestire gli anticoagulanti/antiaggreganti cronici nel perioperatorio di protesi totale di anca e ginocchio.","Revisione narrativa senza sintesi quantitativa propria: raccoglie raccomandazioni esistenti, non genera nuovi dati."],mix:["Come si gestiscono gli anticoagulanti prima e dopo una protesi di ginocchio o d'anca","Una rassegna scritta da chirurghi, internisti e farmacisti spiega come bilanciare il rischio di trombosi con quello di sanguinamento nei pazienti che assumono farmaci anticoagulanti e devono essere operati di protesi.","È una rassegna di raccomandazioni già esistenti, non uno studio con dati originali: utile come guida pratica, non come nuova evidenza."],paz:["Se prendi farmaci per il sangue e devi fare una protesi, ecco come si gestisce in sicurezza","Una rassegna scritta da un gruppo di specialisti spiega come gestire, prima e dopo l'intervento di protesi, i farmaci che fluidificano il sangue, per ridurre sia il rischio di trombosi sia quello di sanguinamento.","È una guida pratica basata su raccomandazioni esistenti, pensata per rendere più sicuro il percorso di chi già assume questi farmaci."],kw:"protesi anticoagulanti · trombosi protesi"},6:{prof:["Dopo la rottura del LCA, BMI e ritardo chirurgico si legano al danno cartilagineo","Una coorte retrospettiva di 80 pazienti mostra che BMI più alto, intervallo trauma-chirurgia più lungo e lesioni meniscali associate si legano in modo indipendente a un danno cartilagineo più esteso al momento della ricostruzione del LCA.","Campione modesto (80 pazienti): gli stessi autori definiscono i risultati esplorativi, da confermare in coorti più ampie."],mix:["Aspettare troppo dopo la rottura del crociato può costare caro alla cartilagine","Uno studio retrospettivo su 80 pazienti mostra che chi arriva all'intervento con un peso corporeo più alto, dopo un'attesa più lunga o con il menisco già lesionato ha più probabilità di avere anche un danno alla cartilagine al momento della ricostruzione del legamento.","Il campione è piccolo e lo studio stesso viene descritto dagli autori come esplorativo: un segnale da confermare, non una regola definitiva."],paz:["Dopo la rottura del legamento del ginocchio, non conviene aspettare troppo per operarsi","Uno studio mostra che chi si opera dopo un'attesa più lunga, o ha un peso corporeo più alto, o ha già una lesione al menisco, arriva più spesso all'intervento con un danno anche alla cartilagine del ginocchio.","È uno studio su un numero limitato di pazienti: un motivo in più, non una certezza assoluta, per non rimandare l'intervento senza necessità."],kw:"crociato rottura tempi · cartilagine ginocchio"},7:{prof:["LCP: una ricostruzione RM più rapida legge bene le lesioni complete, meno le parziali","Uno studio diagnostico su 110 pazienti mostra che una ricostruzione RM assistita da intelligenza artificiale migliora la qualità dell'immagine e riconosce bene le lesioni complete del legamento crociato posteriore (AUC 0,79), ma resta debole sulle lesioni parziali (AUC 0,54 e 0,17).","Nessun confronto con altri algoritmi di ricostruzione; prestazione scarsa proprio sulla categoria clinicamente più difficile."],mix:["Una risonanza magnetica 'più intelligente' aiuta a leggere il legamento posteriore del ginocchio, ma non su tutto","Uno studio su 110 pazienti confrontati con l'artroscopia mostra che un nuovo metodo di ricostruzione delle immagini di risonanza magnetica, assistito da intelligenza artificiale, migliora la qualità dell'immagine e riconosce bene le rotture complete del legamento crociato posteriore, ma è meno affidabile sulle lesioni parziali.","Le lesioni parziali restano le più difficili da leggere anche con questa tecnologia: serve sempre la conferma clinica o artroscopica."],paz:["Una risonanza più avanzata aiuta a vedere meglio le rotture del legamento dietro al ginocchio","Uno studio mostra che una tecnica più moderna di elaborazione delle immagini di risonanza magnetica, aiutata dall'intelligenza artificiale, permette di vedere meglio le rotture complete di uno dei legamenti del ginocchio, ma è meno precisa quando la lesione è solo parziale.","Per le lesioni parziali resta comunque necessaria una valutazione clinica più approfondita, con questa tecnica o senza."],kw:"risonanza ginocchio IA · legamento crociato posteriore"},8:{prof:["Dopo la protesi, due pazienti su tre non riescono a inginocchiarsi o accovacciarsi","Una coorte di 888 ginocchia mostra che a un anno solo il 42% riesce ad accovacciarsi e il 36% a inginocchiarsi; BMI più alto, mobilità preoperatoria scarsa e poca fiducia nel ginocchio prima dell'intervento predicono chi non ci riuscirà.","Monocentrico, popolazione del Sud-Est asiatico: la trasferibilità culturale e clinica ad altri contesti va verificata."],mix:["Dopo la protesi di ginocchio, inginocchiarsi e accovacciarsi restano difficili per molti pazienti","Uno studio su quasi 900 ginocchia operate mostra che, a un anno dall'intervento, la maggioranza dei pazienti non riesce ancora a inginocchiarsi o accovacciarsi comodamente; il peso corporeo, la mobilità di partenza e quanto il paziente si fidava del proprio ginocchio prima dell'intervento sono i fattori che più contano.","È uno studio su una sola popolazione (Singapore): utile per calibrare le aspettative, non generalizzabile senza cautela a ogni contesto."],paz:["Dopo la protesi, inginocchiarsi o stare accovacciati resta difficile per molti: meglio saperlo prima","Uno studio su quasi 900 pazienti operati mostra che circa due su tre non riescono più, a un anno dalla protesi, a inginocchiarsi o accovacciarsi con sicurezza — soprattutto chi arrivava all'intervento con un ginocchio già molto rigido o poco fiducioso nei suoi movimenti.","Conoscerlo prima dell'intervento aiuta a costruire aspettative realistiche, senza promesse che l'intervento da solo non può mantenere."],kw:"protesi ginocchio inginocchiarsi · recupero protesi"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"orange",sec:"res",j:"Journal of ISAKOS",h:"Nel LCA pediatrico, il LET riduce le re-rotture con ogni innesto",v:"revisione sistematica di 51 studi (4.153 pazienti ≤19 anni): l'augmentazione con LET riduce le re-rotture sia su hamstring sia — per la prima volta in questa popolazione — sul tendine quadricipitale, senza compromettere il rientro allo sport",ax:"Olivelle … Sarraf",date:"set 2026",meta:"revisione sistematica PRISMA · 51 studi, 4.153 pz · [III]",pmid:'42680067',doi:'10.1016/j.jisako.2026.101213',journal:"Journal of ISAKOS",authors:"Olivelle A, Guevel B, Sarraf K",design:"Revisione sistematica PRISMA, protocollo registrato su PROSPERO (CRD420251167612): PubMed, Embase, Web of Science e Cochrane Library interrogati dall'inizio ad agosto 2025. Qualità metodologica con Modified Coleman Methodology Score (MCMS), certezza dell'evidenza con GRADE.",pop:"Pazienti pediatrici e adolescenti (≤19 anni) sottoposti a ricostruzione primaria del LCA: 51 studi, 4.153 pazienti, in maggioranza serie di casi retrospettive di qualità media (MCMS medio 58,5; 13,7% giudicati «poor»).",results:"Re-rottura più frequente con hamstring (0-34,6% negli studi) che con osso-tendine-osso o tendine quadricipitale (0-10% in entrambi, negli studi comparativi). L'aggiunta del LET si associa a re-rottura più bassa con ogni tipo di innesto: hamstring+LET 0-5,3% contro 11,9-15% senza LET; tendine quadricipitale+LET 0% contro 7,7% senza LET, nei soli studi comparativi disponibili. Rientro allo sport 42,2-100% a seconda della definizione; tempo medio di rientro 6,4-11,6 mesi; un protocollo restrittivo oltre i 9 mesi si associa a meno revisioni in uno studio comparativo. Intervalli di confidenza non riportati nell'abstract per i confronti fra sottogruppi.",concl:"Gli autori concludono che nel LCA pediatrico l'augmentazione con LET si associa a re-rotture più basse con ogni tipo di innesto, senza compromettere rientro allo sport o esiti funzionali; l'evidenza attuale non giustifica un rientro di routine prima dei 9 mesi senza liberazione funzionale oggettiva.",limits:"Nessun RCT ha confrontato direttamente innesto o timing di rientro nello scheletricamente immaturo · qualità mediamente moderata (13,7% degli studi «poor») · definizioni di rientro eterogenee, confronto diretto fra studi limitato.",perte:"Prima sintesi sistematica che lega esplicitamente tendine quadricipitale e LET nel paziente pediatrico/adolescente — proprio la tua combinazione, qui nella fascia d'età più giovane della tua casistica (dai 14 anni). Il segnale va nella direzione della tua indicazione universale, ma resta costruito su serie retrospettive, non su un confronto randomizzato: alimenta la tensione T1a, non la chiude."},{n:2,mono:"m-jeo",dot:"green",sec:"res",j:"Journal of Experimental Orthopaedics",h:"Nell'osteotomia tibiale alta, il target di correzione conta ancora a 10 anni",v:"coorte di 103 ginocchia randomizzate a due target di correzione (70% vs 62% della linea di carico): entrambi perdono correzione nel tempo, ma il 62% resta più spesso sotto-corretto ed è legato a più conversioni a protesi",ax:"Jung … Takeuchi",date:"ago 2026",meta:"coorte, cort. randomizzata (follow-up 10 anni) · 103 ginocchia · [II]",pmid:'42677189',doi:'10.1002/jeo2.70900',journal:"Journal of Experimental Orthopaedics",authors:"Jung WH, Paneliya M, Goyal S, Kim DH, Takeuchi R",design:"Revisione retrospettiva a 10 anni di una coorte inizialmente randomizzata (1 chirurgo) a due target intraoperatori di linea di carico (weight-bearing line, WBL) nell'osteotomia tibiale alta a cuneo di apertura mediale con placca a stabilità angolare: 70% (n=50) o 62% (n=53). Endpoint primario: conversione a protesi totale di ginocchio (TKA).",pop:"103 ginocchia operate da un solo chirurgo, follow-up radiografico e clinico fino a 10 anni.",results:"A 6 mesi la WBL media era 71,4% (gruppo 70%) e 62,2% (gruppo 62%). Entrambi i gruppi perdono correzione in modo simile a 10 anni (-5,5 contro -4,8 punti percentuali; p=0,429), ma il gruppo 62% resta sotto-corretto nel 45% dei casi contro il 13% del gruppo 70% (p<0,001); le ginocchia sotto-corrette convertono a protesi più spesso (36,7% contro 9,6%; p=0,012). Conversione complessiva a protesi 22,0% (70%) contro 24,5% (62%) — ricalcolato con test/potenza.py sui conteggi grezzi (11/50 vs 13/53): rischio relativo 0,90, IC 95% 0,44-1,81, un intervallo che non esclude né una protezione importante né un rischio quasi raddoppiato; gli stessi autori dichiarano il confronto sottopotente (potenza 4,8%). Punteggi clinici sovrapponibili fra i gruppi.",concl:"Gli autori concludono che un target vicino al 70%, senza superarlo, potrebbe ridurre sia il rischio di sotto-correzione tardiva sia quello di sovra-correzione precoce; propongono un target intermedio da confermare in uno studio più ampio e adeguatamente potenziato.",limits:"Confronto sulla conversione complessiva a protesi dichiarato sottopotente dagli stessi autori · monocentrico, un solo chirurgo · ipotesi di proporzionalità dei rischi violata nel tempo, analisi statistica più complessa del solito Cox semplice.",perte:"Non è la combinazione con la rifissazione della radice meniscale che eseguiresti insieme (T2b), ma è un dato diretto sul parametro tecnico che decidi tu al tavolo operatorio — il target di correzione — con follow-up a 10 anni: un'indicazione a restare vicino, ma non oltre, il 70% della linea di carico."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Arthroscopy, Sports Medicine, and Rehabilitation",h:"Nel menisco pediatrico, la sutura protegge dall'artrosi post-traumatica più della resezione",v:"registro amministrativo su oltre 10.000 pazienti pediatrici: a 10 anni l'artrosi post-traumatica è meno frequente dopo sutura meniscale che dopo meniscectomia, un secondo intervento di 'ripristino del movimento' è il fattore di rischio più forte in entrambi i gruppi",ax:"Hiredesai … Patel",date:"ago 2026",meta:"coorte retrospettiva di registro · 10.352 pz · [III]",pmid:'42676605',doi:'10.1002/ars2.70067',journal:"Arthroscopy, Sports Medicine, and Rehabilitation",authors:"Hiredesai AN, Holle AM, Patel JR, Koschmeder KT, Tummala SV, Vaughn JM, Patel KA",design:"Coorte retrospettiva sul database amministrativo PearlDiver, pazienti pediatrici (≤16 anni) sottoposti a meniscectomia o sutura meniscale isolata e primaria (2010-2023), con almeno 5 anni di follow-up; esclusi altri traumi, interventi o sindromi concomitanti al ginocchio. Regressione logistica e di Cox multivariabile per i fattori di rischio.",pop:"7.555 meniscectomie (età media 14,7 anni, 50% femmine) e 2.797 suture meniscali (età media 14,4 anni, 46% femmine).",results:"Artrosi post-traumatica (PTOA, per codice di fatturazione) a 5 anni: 2,2% dopo meniscectomia, 1,4% dopo sutura; a 10 anni: 2,3% e 1,5%. Ricalcolato con test/potenza.py sui conteggi grezzi (42/2.797 sutura vs 174/7.555 meniscectomia a 10 anni): rischio relativo 0,65, IC 95% 0,47-0,91 — un intervallo che esclude l'assenza di differenza, a favore della sutura. Nella meniscectomia, i fattori di rischio indipendenti per PTOA a 10 anni sono un secondo intervento di «ripristino del movimento» (hazard ratio 6,28; p<0,001), età ≥12 anni all'intervento (HR 4,84; p=0,027) e obesità (HR 1,84; p<0,001); nella sutura, il secondo intervento di ripristino del movimento (HR 5,23; p=0,023) e la depressione (HR 2,02; p=0,027).",concl:"Gli autori concludono che l'incidenza di artrosi post-traumatica a 10 anni resta bassa dopo chirurgia meniscale pediatrica isolata, ma è più bassa dopo sutura che dopo meniscectomia; un secondo intervento per rigidità articolare è il segnale di allarme più forte in entrambi i gruppi.",limits:"Diagnosi di artrosi per codice di fatturazione amministrativo, non per referto radiografico standardizzato · nessun dato su tipo, sede o riparabilità della lesione meniscale · database USA, generalizzabilità al tuo contesto da verificare.",perte:"Rinforza — su un registro molto più ampio del solito e nella fascia d'età che segui dai 14 anni — il principio già consolidato per te: riparare il menisco, quando possibile, protegge meglio della resezione anche a lungo termine nel paziente giovane."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"SICOT-J",h:"Nella protesi robotica, l'allineamento funzionale riduce i release ma non batte il classico a un anno",v:"meta-analisi di 6 studi comparativi (645 protesi): l'allineamento funzionale richiede meno release dei tessuti molli e recupera prima il movimento, ma a un anno la funzione è sovrapponibile all'allineamento meccanico classico",ax:"Jamaleddine … Kouyoumdjian",date:"set 2026",meta:"meta-analisi di studi comparativi · 6 studi, 645 protesi · [II]",pmid:'42679215',doi:'10.1051/sicotj/2026061',journal:"SICOT-J",authors:"Jamaleddine Y, Maroun R, Assi C, Khoury A, Kouyoumdjian P",design:"Meta-analisi di studi comparativi (Medline, Cochrane Library, Google Scholar dall'inizio a dicembre 2025) su allineamento funzionale vs meccanico in protesi totale di ginocchio robot-assistita primaria. Esiti: release aggiuntivo dei tessuti molli, movimento articolare, Forgotten Joint Score-12 (FJS-12), miglioramento funzionale a 1 anno, durata operatoria. Differenze medie e odds ratio aggregati.",pop:"6 studi comparativi, 645 protesi totali di ginocchio robot-assistite primarie.",results:"L'allineamento meccanico richiede più spesso un release aggiuntivo dei tessuti molli rispetto al funzionale (OR 5,38; IC 95% 2,71-10,69; p<0,00001). Il funzionale recupera più movimento articolare nelle prime 6 settimane (differenza media -4,64°; IC 95% -7,07/-2,21; p=0,0002), differenza non più significativa a 6 mesi (differenza media -1,13°; IC 95% -8,24/5,98; p=0,76). Il FJS-12 è simile a 3 mesi ma favorisce il funzionale a 6 mesi (differenza media -10,74; IC 95% -13,65/-7,83; p<0,00001), senza però raggiungere la soglia di rilevanza clinica stabilita. Il miglioramento funzionale a 1 anno è simile fra i gruppi; il tempo operatorio favorisce statisticamente il funzionale, ma di poco.",concl:"Gli autori concludono che l'allineamento funzionale riduce i release aggiuntivi e anticipa il recupero del movimento, ma questi vantaggi precoci non si traducono in un miglioramento funzionale superiore a 1 anno; servono confronti standardizzati più lunghi.",limits:"Solo 6 studi, 645 protesi in totale · eterogeneità delle piattaforme robotiche incluse, VELYS non isolato come categoria propria · nessuna sottoanalisi per piattaforma dichiarata nell'abstract.",perte:"Non risponde su VELYS in modo specifico, ma inquadra bene il dibattito allineamento funzionale/meccanico che accompagna ogni discussione sulla tua protesi robotica: meno gesti intraoperatori aggiuntivi e ripresa più rapida, senza un vantaggio funzionale dimostrato a un anno — coerente con RACER-Knee (21 agosto) e con la revisione critica del 1° settembre."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Clinical and Applied Thrombosis/Hemostasis",h:"Protesi di ginocchio e anca: una rassegna pratica su anticoagulanti e tromboprofilassi",v:"revisione narrativa multidisciplinare su come gestire la tromboprofilassi perioperatoria e i pazienti già in anticoagulazione cronica prima e dopo protesi totale di anca e ginocchio",ax:"Cronin … Segal",date:"set 2026",meta:"revisione narrativa multidisciplinare · [V]",pmid:'42677912',doi:'10.1177/10760296261483876',journal:"Clinical and Applied Thrombosis/Hemostasis",authors:"Cronin M, Shraibman S, Intintoli AM, Bitterman A, Segal A",design:"Revisione narrativa multidisciplinare (chirurgia ortopedica, medicina ospedaliera, farmacia clinica) sulla stratificazione del rischio tromboembolico ed emorragico e sulla gestione perioperatoria degli anticoagulanti/antiaggreganti cronici in protesi totale di anca e ginocchio.",pop:"Non applicabile: sintesi narrativa di linee guida e letteratura esistente, nessuna coorte propria.",results:"Nessun dato quantitativo aggregato proprio: la rassegna riassume raccomandazioni esistenti su stratificazione del rischio, scelta dell'agente tromboprofilattico e gestione perioperatoria di anticoagulanti/antiaggreganti cronici. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori concludono che un regime tromboprofilattico e di gestione degli anticoagulanti costruito sul singolo paziente, con un team multidisciplinare, bilancia meglio il rischio di trombosi e quello di sanguinamento rispetto a un protocollo uniforme.",limits:"Revisione narrativa, nessun protocollo sistematico dichiarato · nessuna sintesi quantitativa · orientata al contesto statunitense, dosaggi e disponibilità dei farmaci non sempre trasferibili al tuo.",perte:"Complemento pratico al dato di registro britannico sul tromboembolismo dopo protesi (476.620 procedure, 1° settembre): qui il taglio è la gestione clinica quotidiana del paziente già in terapia anticoagulante, un tema che ricorre a ogni tua lista operatoria."},{n:6,mono:"m-gray",dot:"green",sec:"res",j:"Medicine",h:"Dopo la rottura del LCA, BMI e ritardo chirurgico pesano sul danno cartilagineo",v:"coorte retrospettiva cinese di 80 pazienti: un BMI più alto, un intervallo più lungo fra trauma e chirurgia e le lesioni meniscali associate si legano in modo indipendente a un danno cartilagineo più esteso al momento dell'intervento",ax:"Xiong … Zhang",date:"ago 2026",meta:"coorte retrospettiva monocentrica · 80 pz · [III]",pmid:'42675763',doi:'10.1097/MD.0000000000050374',journal:"Medicine",authors:"Xiong X, Li D, Li Y, Zhang Q",design:"Studio osservazionale retrospettivo monocentrico, adulti con rottura primaria unilaterale del LCA (giugno 2020-giugno 2025); danno cartilagineo classificato con il sistema ICRS su RM e/o valutazione artroscopica (danno = grado ICRS ≥2). Regressione logistica uni e multivariabile.",pop:"80 pazienti con rottura primaria del LCA; 32 (40,0%) con danno cartilagineo concomitante.",results:"I pazienti con danno cartilagineo avevano un BMI più alto e un intervallo trauma-chirurgia più lungo, e più spesso lesioni meniscali sia mediali sia laterali. All'analisi multivariabile, BMI più alto, intervallo trauma-chirurgia più lungo e lesioni meniscali sia mediali sia laterali restano indipendentemente associati al danno cartilagineo; età e edema osseo/contusione ossea non risultano associati in modo indipendente. Valori numerici esatti (OR, IC 95%) non riportati nell'abstract.",concl:"Gli autori concludono che fattori legati al carico meccanico e la patologia meniscale concomitante sono i correlati principali del danno cartilagineo dopo rottura del LCA, e possono orientare la stratificazione del rischio alla presentazione.",limits:"Campione modesto (80 pazienti, 32 con danno) · monocentrico, retrospettivo · gli stessi autori definiscono i risultati esplorativi e da confermare in coorti più ampie.",perte:"Un motivo tecnico in più per non allungare i tempi fra infortunio e ricostruzione quando la situazione clinica lo consente, specie nel paziente con BMI elevato o lesioni meniscali associate — coerente con la tua pratica di operare senza attese ingiustificate."},{n:7,mono:"m-gray",dot:"green",sec:"res",j:"Medicine",h:"Una ricostruzione RM più veloce distingue bene le lesioni complete del LCP, meno le parziali",v:"110 pazienti, confronto con l'artroscopia: la ricostruzione 'intelligente' delle immagini RM migliora nettamente la qualità dell'immagine e riconosce bene le lesioni complete del legamento crociato posteriore, ma resta debole sulle lesioni parziali",ax:"Peng … Zeng",date:"ago 2026",meta:"studio diagnostico retrospettivo, standard artroscopico · 110 pz · [III]",pmid:'42675753',doi:'10.1097/MD.0000000000050292',journal:"Medicine",authors:"Peng X, Xu Y, Yang Y, Wei J, Wen S, Huang L, Li L, Zeng Z",design:"Studio retrospettivo di accuratezza diagnostica: RM preoperatoria ricostruita con un algoritmo di intelligenza artificiale (IQMR) confrontata con la ricostruzione standard, referto in doppio cieco da due radiologi, standard di riferimento l'artroscopia. Curve ROC per lesioni complete (grado 3) e parziali (gradi 1-2) del legamento crociato posteriore (LCP).",pop:"110 pazienti con lesione del LCP confermata artroscopicamente.",results:"La ricostruzione IQMR ottiene una qualità d'immagine soggettiva e oggettiva significativamente superiore alla standard (p<0,005 su tutti i parametri), con accordo interosservatore da buono a eccellente (kappa pesato 0,63-0,97). Accuratezza diagnostica contro l'artroscopia: area sotto la curva 0,79 (p<0,05) per le lesioni complete, ma solo 0,54 e 0,17 per le lesioni parziali di grado 1 e 2; accordo complessivo RM-artroscopia moderato (kappa 0,57).",concl:"Gli autori concludono che la ricostruzione IQMR migliora la qualità dell'immagine e la diagnosi delle lesioni complete del LCP, ma non risolve il problema clinico più difficile — riconoscere le lesioni parziali — che richiede ancora conferma artroscopica o clinica.",limits:"Monocentrico, retrospettivo · nessun confronto con altri algoritmi di ricostruzione IA · prestazione scarsa proprio sulle lesioni parziali, la categoria più difficile da gestire clinicamente.",perte:"Un promemoria tecnico utile quando referti la RM prima di una ricostruzione del LCP: una lesione parziale letta come tale alla RM va comunque confermata in artroscopia, indipendentemente da quanto sia «pulita» la ricostruzione dell'immagine — l'intelligenza artificiale qui aiuta la qualità dell'immagine, non ancora la diagnosi difficile."},{n:8,mono:"m-gray",dot:"white",sec:"res",j:"The Journal of Arthroplasty",h:"Dopo la protesi, due pazienti su tre non riescono a inginocchiarsi o accovacciarsi",v:"888 ginocchia in Singapore: a un anno il 42% riesce ad accovacciarsi e il 36% a inginocchiarsi; BMI, movimento preoperatorio scarso e poca fiducia nel ginocchio prima dell'intervento predicono chi non ci riuscirà",ax:"Sethi … Guoping Tan",date:"set 2026",meta:"coorte retrospettiva monocentrica · 888 ginocchia · [III]",pmid:'42679867',doi:'10.1016/j.arth.2026.08.053',journal:"The Journal of Arthroplasty",authors:"Sethi E, Mohan R, Leng TT, Kunnasegaran R, Jie Michael YG, Ho Poh W, Hong TY, Peng LY, Guoping Tan K",design:"Analisi retrospettiva monocentrica (Singapore) su predittori pre-, intra- e postoperatori della capacità di inginocchiarsi e/o accovacciarsi a 1 anno da protesi primaria di ginocchio, con modelli uni e multivariabili.",pop:"888 ginocchia in 830 pazienti sottoposti a protesi primaria di ginocchio (totale o monocompartimentale).",results:"A 1 anno: 42% dei pazienti in grado di accovacciarsi, 36% di inginocchiarsi, 30% di fare entrambe le cose; incapacità rispettivamente nel 58%, 64% e 70%. La capacità si associa a maggiore flessione postoperatoria (p=0,028), maggiore range di movimento (p=0,002) e maggiore fiducia preoperatoria nel ginocchio misurata con l'Oxford Knee Score domanda 4 (p<0,001). L'incapacità è predetta in modo indipendente da BMI più alto, range di movimento e flessione preoperatori più scarsi, poca fiducia preoperatoria, età più avanzata e sesso femminile (tutti p<0,05). La protesi monocompartimentale mediale mostra una tendenza non significativa a un miglior recupero in alta flessione.",concl:"Gli autori concludono che inginocchiarsi e accovacciarsi restano impossibili per circa due terzi dei pazienti dopo protesi di ginocchio, e che ottimizzare BMI, range di movimento e fiducia preoperatoria attraverso prehabilitation ed educazione realistica delle aspettative può migliorare la soddisfazione postoperatoria.",limits:"Monocentrico, popolazione del Sud-Est asiatico: trasferibilità ad altri contesti culturali e articolari da verificare · nessun confronto randomizzato fra tecniche o impianti · autovalutazione della capacità di inginocchiarsi/accovacciarsi, non misura strumentale.",perte:"Un dato utile per il colloquio preoperatorio, soprattutto con pazienti per cui inginocchiarsi o accovacciarsi conta nella vita quotidiana: le aspettative vanno calibrate su BMI, mobilità di partenza e fiducia nel ginocchio prima ancora di operare, non solo sulla tecnica scelta."}];
var SUGGQ=[{k:"kol",n:"Khaled Sarraf",w:"Imperial College Healthcare NHS Trust, St Mary's Hospital, Londra",r:"Ultimo autore della revisione sistematica di oggi su innesto e LET nel LCA pediatrico/adolescenziale — proprio l'incrocio innesto+rinforzo laterale che segui tu, qui applicato alla fascia d'età più giovane della tua casistica (dai 14 anni). Nome nuovo nella tua rete, corrispondenza tecnica diretta."}];
var BRIEF_TEXT="Mercoledì 2 settembre. Otto lavori oggi, uno arancione. Il pick va a una revisione sistematica di 51 studi su 4.153 pazienti pediatrici e adolescenti operati di legamento crociato anteriore: aggiungere una tenodesi extra-articolare laterale (LET) si associa a meno re-rotture con ogni tipo di innesto, e per la prima volta il dato tocca anche il tendine quadricipitale — 0% di re-rottura con LET contro 7,7% senza, proprio la tua combinazione, qui nella fascia d'età più giovane della tua casistica. È un segnale che va nella direzione della tua indicazione universale, non una dimostrazione: la base resta fatta di serie retrospettive, nessun RCT ha mai confrontato innesto o LET nello scheletricamente immaturo. Il resto della giornata gravita sulla protesi e sulla tecnica quotidiana. Un confronto a 10 anni fra due target di correzione nell'osteotomia tibiale alta (70% e 62% della linea di carico) mostra che il target più basso resta sotto-corretto più spesso e converte di più a protesi, anche se il confronto complessivo è dichiarato sottopotente dagli stessi autori. Un registro su oltre 10mila pazienti pediatrici conferma, su una scala molto più ampia del solito, che riparare il menisco protegge dall'artrosi post-traumatica più che asportarlo. Sulla protesi robotica, una meta-analisi di 6 studi mostra che l'allineamento funzionale riduce i gesti aggiuntivi e accelera il recupero iniziale del movimento, ma a un anno il risultato funzionale è simile all'allineamento meccanico classico — coerente con RACER-Knee e con la revisione critica di ieri. Chiude un dato di aspettative concrete: a un anno dalla protesi, in una coorte di quasi 900 ginocchia operate a Singapore, due pazienti su tre non riescono ancora a inginocchiarsi o accovacciarsi, e i fattori predittivi (peso corporeo, mobilità e fiducia nel ginocchio prima dell'intervento) sono tutti calibrabili già nel colloquio preoperatorio. Nessuna tensione chiusa oggi, ma T1a si arricchisce del primo dato pediatrico diretto sul tendine quadricipitale con LET. Il raccoglitore notturno non è passato: nessun richiamo nuovo comunque, ritrattazioni verificate a mano su tutte le 154 citazioni storiche più le 32 di oggi — nessuna trovata.";
var BRIEF_DIALOGO=[{chi:"A",t:"Buongiorno. Otto lavori oggi, uno solo arancione, ed è un lavoro che parla direttamente della tua pratica."},{chi:"B",t:"Comincia dal pick."},{chi:"A",t:"Una revisione sistematica di 51 studi, oltre 4mila pazienti pediatrici e adolescenti operati di crociato anteriore: aggiungere il rinforzo laterale, il LET, riduce le nuove rotture con ogni tipo di innesto."},{chi:"B",t:"Anche col tendine quadricipitale, quello che usi tu?"},{chi:"A",t:"Sì, per la prima volta: zero per cento di re-rottura con LET contro il 7,7% senza, nei pazienti più giovani della tua casistica. Ma sono serie retrospettive, non un confronto randomizzato: un segnale forte, non ancora una prova."},{chi:"B",t:"E il resto della giornata?"},{chi:"A",t:"Molto concreto. Un confronto a dieci anni sull'osteotomia tibiale alta mostra che correggere fino a un target vicino al 70% della linea di carico, senza superarlo, riduce sia la sotto-correzione sia il rischio di finire in protesi."},{chi:"B",t:"E sul menisco nei ragazzi?"},{chi:"A",t:"Un registro enorme, oltre 10mila pazienti pediatrici, conferma quello che già sapevi: riparare protegge dall'artrosi precoce più che asportare, anche a dieci anni di distanza."},{chi:"B",t:"E sulla protesi robotica, qualcosa di nuovo?"},{chi:"A",t:"Una meta-analisi di sei studi: l'allineamento funzionale richiede meno gesti aggiuntivi e recupera il movimento più in fretta all'inizio, ma a un anno il risultato è uguale all'allineamento classico. Stesso messaggio di RACER-Knee e della revisione critica di ieri."},{chi:"B",t:"Come si chiude?"},{chi:"A",t:"Con un dato utile per il colloquio preoperatorio: a un anno dalla protesi, due pazienti su tre non riescono ancora a inginocchiarsi o accovacciarsi, e si può prevedere chi avrà più difficoltà già prima di operare."},{chi:"B",t:"Qualcosa che non ha funzionato stanotte?"},{chi:"A",t:"Il raccoglitore automatico non è passato: nessun nuovo richiamo comunque, e le ritrattazioni le ho verificate a mano su tutte le citazioni storiche — nessuna trovata."}];
